/* DAWAH X — ahmad, অধ্যায় 93 · খণ্ড 93 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][93]=[[18401,18401,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَظْرَةِ ‏ ‏الْفَجْأَةِ ‏ ‏فَأَمَرَنِي فَقَالَ ‏ ‏اصْرِفْ بَصَرَكَ ‏","","",""],[18402,18402,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِيَصْدُرْ ‏ ‏الْمُصَدِّقُ مِنْ عِنْدِكُمْ وَهُوَ رَاضٍ ‏","","",""],[18403,18403,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرًا ‏ ‏يَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى النُّصْحِ لِكُلِّ مُسْلِمٍ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏زِيَادٍ ‏ ‏فَإِنِّي لَكُمْ لَنَاصِحٌ ‏","","",""],[18404,18404,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ ابْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ قَوْمًا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏مُجْتَابِي ‏ ‏النِّمَارِ ‏ ‏فَحَثَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ عَلَى ‏ ‏الصَّدَقَةِ ‏ ‏فَأَبْطَئُوا حَتَّى رُئِيَ ذَلِكَ فِي وَجْهِهِ فَجَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏بِقِطْعَةِ ‏ ‏تِبْرٍ ‏ ‏فَطَرَحَهَا فَتَتَابَعَ النَّاسُ حَتَّى عُرِفَ ذَلِكَ فِي وَجْهِهِ فَقَالَ ‏ ‏مَنْ سَنَّ سُنَّةً حَسَنَةً فَعُمِلَ بِهَا مِنْ بَعْدِهِ كَانَ لَهُ أَجْرُهَا وَمِثْلُ أَجْرِ مَنْ عَمِلَ بِهَا مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ سُنَّةً سَيِّئَةً عُمِلَ بِهَا مِنْ بَعْدِهِ كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَوِزْرُ ‏ ‏مَنْ عَمِلَ بِهَا وَلَا يُنْقِصُ ذَلِكَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْئًا ‏","","",""],[18405,18405,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَتَوَضَّأُ مِنْ ‏ ‏مِطْهَرَةٍ ‏ ‏وَمَسَحَ عَلَى خُفَّيْهِ فَقَالُوا أَتَمْسَحُ عَلَى خُفَّيْكَ فَقَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً يَمْسَحُ عَلَى خُفَّيْهِ ‏ ‏فَكَانَ هَذَا الْحَدِيثُ يُعْجِبُ أَصْحَابَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏يَقُولُونَ إِنَّمَا كَانَ إِسْلَامُهُ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏","","",""],[18406,18406,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ يَعْنِي ابْنَ صُبَيْحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هِلَالٍ الْعَبْسِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَثَّنَا عَلَى ‏ ‏الصَّدَقَةِ ‏ ‏فَأَبْطَأَ النَّاسُ حَتَّى رُئِيَ فِي وَجْهِهِ الْغَضَبُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً حَتَّى بَانَ ‏ ‏ثُمَّ إِنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏جَاءَ ‏ ‏بِصُرَّةٍ ‏ ‏فَأَعْطَاهَا إِيَّاهُ ثُمَّ تَتَابَعَ النَّاسُ فَأَعْطَوْا حَتَّى رُئِيَ فِي وَجْهِهِ السُّرُورُ فَقَالَ ‏ ‏مَنْ سَنَّ سُنَّةً حَسَنَةً كَانَ لَهُ أَجْرُهَا وَمِثْلُ أَجْرِ مَنْ عَمِلَ بِهَا مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَمِثْلُ ‏ ‏وِزْرِ ‏ ‏مَنْ عَمِلَ بِهَا مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏ ‏قَالَ مَرَّةً ‏ ‏يَعْنِي ‏ ‏أَبَا مُعَاوِيَةَ ‏ ‏مِنْ غَيْرِ أَنْ يَنْقُصَ ‏","","",""],[18407,18407,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ وَهُوَ الضَّرِيرُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18408,18408,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تُرِيحُنِي مِنْ ‏ ‏ذِي الْخَلَصَةِ ‏ ‏وَكَانَ بَيْتًا فِي ‏ ‏خَثْعَمَ ‏ ‏يُسَمَّى كَعْبَةَ الْيَمَانِيَةِ قَالَ فَانْطَلَقْتُ فِي خَمْسِينَ وَمِائَةِ فَارِسٍ مِنْ ‏ ‏أَحْمَسَ ‏ ‏وَكَانُوا أَصْحَابَ خَيْلٍ فَأَخْبَرْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي لَا أَثْبُتُ عَلَى الْخَيْلِ فَضَرَبَ فِي صَدْرِي حَتَّى رَأَيْتُ أَثَرَ أَصَابِعِهِ فِي صَدْرِي وَقَالَ ‏ ‏اللَّهُمَّ ثَبِّتْهُ وَاجْعَلْهُ هَادِيًا مَهْدِيًّا فَانْطَلَقَ إِلَيْهَا فَكَسَّرَهَا وَحَرَّقَهَا فَأَرْسَلَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَشِّرُهُ فَقَالَ رَسُولُ ‏ ‏جَرِيرٍ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا جِئْتُكَ حَتَّى تَرَكْتُهَا كَأَنَّهَا جَمَلٌ أَجْرَبُ فَبَارَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى خَيْلِ ‏ ‏أَحْمَسَ ‏ ‏وَرِجَالِهَا خَمْسَ مَرَّاتٍ ‏","","",""],[18409,18409,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ نَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ ‏ ‏أَمَا إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ كَمَا تَرَوْنَ هَذَا لَا ‏ ‏تُضَامُونَ ‏ ‏أَوْ لَا ‏ ‏تُضَارُّونَ ‏ ‏شَكَّ ‏ ‏إِسْمَاعِيلُ ‏ ‏فِي رُؤْيَتِهِ فَإِنْ اسْتَطَعْتُمْ أَنْ لَا ‏ ‏تُغْلَبُوا ‏ ‏عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ثُمَّ قَالَ فَ ‏ { ‏سَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا ‏}","","",""],[18410,18410,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ هِلَالٍ الْعَبْسِيُّ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَسُنُّ عَبْدٌ سُنَّةً صَالِحَةً يَعْمَلُ بِهَا مَنْ بَعْدَهُ إِلَّا كَانَ لَهُ مِثْلُ أَجْرِ مَنْ عَمِلَ بِهَا لَا يُنْقَصُ مِنْ أُجُورِهِمْ شَيْءٌ وَلَا يَسُنُّ عَبْدٌ سُنَّةَ سُوءٍ يَعْمَلُ بِهَا مَنْ بَعْدَهُ إِلَّا كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَوِزْرُ ‏ ‏مَنْ عَمِلَ بِهَا لَا يُنْقَصُ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ قَالَ وَأَتَاهُ نَاسٌ مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏فَقَالُوا يَا نَبِيَّ اللَّهِ يَأْتِينَا نَاسٌ مِنْ مُصَدِّقِيكَ يَظْلِمُونَا قَالَ أَرْضُوا مُصَدِّقَكُمْ وَإِنْ ظَلَمَ قَالَ أَرْضُوا مُصَدِّقَكُمْ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏فَمَا صَدَرَ عَنِّي مُصَدِّقٌ مُنْذُ سَمِعْتُهَا مِنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا وَهُوَ عَنِّي رَاضٍ ‏","","",""],[18411,18411,"","","‏ ‏قَالَ ‏ ‏وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يُحْرَمْ الرِّفْقَ يُحْرَمْ الْخَيْرَ ‏","","",""],[18412,18412,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ ‏ ‏خَالُ ‏ ‏الْمُنْذِرِ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏أَبِي جَرِيرٍ ‏ ‏بِالْبَوَارِيجِ ‏ ‏فِي ‏ ‏السَّوَادِ ‏ ‏فَرَاجَعْتُ الْبَقَرَ فَرَأَى بَقَرَةً أَنْكَرَهَا فَقَالَ مَا هَذِهِ الْبَقَرَةُ قَالَ بَقَرَةٌ لَحِقَتْ بِالْبَقَرِ فَأَمَرَ بِهَا فَطُرِدَتْ حَتَّى تَوَارَتْ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يُؤْوِي الضَّالَّةَ إِلَّا ضَالٌّ ‏","","",""],[18413,18413,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي عَنْهُ مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ فِي وَجْهِي ‏","","",""],[18414,18414,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏أَبَقَ ‏ ‏الْعَبْدُ بَرِئَتْ مِنْهُ الذِّمَّةُ ‏","","",""],[18415,18415,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْمُخَرِّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الصَّلْتُ بْنُ مَسْعُودٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنٌ لِجَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏نَعْلُ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏طُولُهَا ذِرَاعٌ ‏","","",""],[18416,18416,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الْيَقْظَانِ عُثْمَانَ بْنِ عُمَيْرٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّحْدُ ‏ ‏لَنَا ‏ ‏وَالشَّقُّ ‏ ‏لِأَهْلِ الْكِتَابِ ‏","","",""],[18417,18417,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏طَارِقٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏طَارِقٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى نِسْوَةٍ فَسَلَّمَ عَلَيْهِنَّ ‏","","",""],[18418,18418,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏أَوْلِيَاءُ بَعْضُهُمْ لِبَعْضٍ وَالطُّلَقَاءُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَالْعُتَقَاءُ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏فَحَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[18419,18419,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ قَوْمٍ يَكُونُ بَيْنَ أَظْهُرِهِمْ مَنْ يَعْمَلُ بِالْمَعَاصِي هُمْ أَعَزُّ مِنْهُ وَأَمْنَعُ لَمْ يُغَيِّرُوا عَلَيْهِ إِلَّا أَصَابَهُمْ اللَّهُ عَزَّ وَجَلَّ مِنْهُ بِعِقَابٍ ‏","","",""],[18420,18420,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ بْنَ عَمْرِو بْنِ جَرِيرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي حَجَّةِ الْوَدَاعِ ‏ ‏لِجَرِيرٍ ‏ ‏اسْتَنْصِتْ النَّاسَ وَقَالَ قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[18421,18421,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هِلَالٍ الْعَبْسِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الطُّلَقَاءُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَالْعُتَقَاءُ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ فِي الدُّنْيَا وَالْآخِرَةِ ‏ ‏وَالْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[18422,18422,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِطْ عَلَيَّ قَالَ ‏ ‏تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُصَلِّي الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَنْصَحُ لِلْمُسْلِمِ وَتَبْرَأُ مِنْ الْكَافِرِ ‏","","",""],[18423,18423,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ ‏ ‏الْبَيْتِ ‏ ‏وَصَوْمِ رَمَضَانَ ‏","","",""],[18424,18424,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ بْنِ عُلَاثَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ بْنِ مَالِكٍ الْجَزْرِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏أَنَا أَسْلَمْتُ بَعْدَ مَا أُنْزِلَتْ ‏ ‏الْمَائِدَةُ ‏ ‏وَأَنَا ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ ‏ ‏بَعْدَمَا أَسْلَمْتُ ‏","","",""],[18425,18425,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَا ثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخَاكُمْ ‏ ‏النَّجَاشِيَّ ‏ ‏قَدْ مَاتَ فَاسْتَغْفِرُوا لَهُ ‏","","",""],[18426,18426,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَدْخُلُ ‏ ‏الْمَخْرَجَ ‏ ‏فِي خُفَّيْهِ ثُمَّ يَخْرُجُ فَيَتَوَضَّأُ وَيَمْسَحُ عَلَيْهِمَا ‏","","",""],[18427,18427,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَلَقِيتُ بِهَا رَجُلَيْنِ ‏ ‏ذَا كَلَاعٍ ‏ ‏وَذَا عَمْرٍو ‏ ‏قَالَ وَأَخْبَرْتُهُمَا شَيْئًا مِنْ خَبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ أَقْبَلْنَا فَإِذَا قَدْ رُفِعَ لَنَا رَكْبٌ مِنْ قِبَلِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَسَأَلْنَاهُمْ مَا الْخَبَرُ قَالَ فَقَالُوا قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتُخْلِفَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَالنَّاسُ صَالِحُونَ قَالَ فَقَالَ لِي أَخْبِرْ صَاحِبَكَ قَالَ فَرَجَعَا ثُمَّ لَقِيتُ ‏ ‏ذَا عَمْرٍو ‏ ‏فَقَالَ لِي يَا ‏ ‏جَرِيرُ ‏ ‏إِنَّكُمْ لَنْ تَزَالُوا بِخَيْرٍ مَا إِذَا هَلَكَ أَمِيرٌ ثُمَّ تَأَمَّرْتُمْ فِي آخَرَ فَإِذَا كَانَتْ بِالسَّيْفِ غَضِبْتُمْ غَضَبَ الْمُلُوكِ وَرَضِيتُمْ رِضَا الْمُلُوكِ ‏","","",""],[18428,18428,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ يَزِيدَ الْأَوْدِيَّ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَبَقَ ‏ ‏الْعَبْدُ فَلَحِقَ بِالْعَدُوِّ فَمَاتَ فَهُوَ كَافِرٌ ‏","","",""],[18429,18429,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ يَزِيدَ الْأَوْدِيُّ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ ‏ ‏الْبَيْتِ ‏ ‏وَصِيَامِ رَمَضَانَ ‏","","",""],[18430,18430,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرٌ ‏ ‏لَمَّا دَنَوْتُ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَخْتُ رَاحِلَتِي ثُمَّ حَلَلْتُ عَيْبَتِي ثُمَّ لَبِسْتُ حُلَّتِي ثُمَّ دَخَلْتُ الْمَسْجِدَ فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَرَمَانِي النَّاسُ ‏ ‏بِالْحَدَقِ ‏ ‏قَالَ فَقُلْتُ لِجَلِيسِي يَا عَبْدَ اللَّهِ هَلْ ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَمْرِي شَيْئًا قَالَ نَعَمْ ذَكَرَكَ بِأَحْسَنِ الذِّكْرِ بَيْنَمَا هُوَ يَخْطُبُ إِذْ عَرَضَ لَهُ فِي خُطْبَتِهِ فَقَالَ إِنَّهُ ‏ ‏سَيَدْخُلُ عَلَيْكُمْ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏مِنْ خَيْرِ ذِي يَمَنٍ أَلَا وَإِنَّ عَلَى وَجْهِهِ ‏ ‏مَسْحَةُ مَلَكٍ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏فَحَمِدْتُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[18431,18431,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالسَّمْعِ وَالطَّاعَةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏","","",""],[18432,18432,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرٌ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ وَعَلَى أَنْ أَنْصَحَ لِكُلِّ مُسْلِمٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏جَرِيرٌ ‏ ‏إِذَا اشْتَرَى الشَّيْءَ وَكَانَ أَعْجَبَ إِلَيْهِ مِنْ ثَمَنِهِ قَالَ لِصَاحِبِهِ تَعْلَمَنَّ وَاللَّهِ لَمَا أَخَذْنَا أَحَبُّ إِلَيْنَا مِمَّا أَعْطَيْنَاكَ كَأَنَّهُ يُرِيدُ بِذَلِكَ الْوَفَاءَ ‏","","",""],[18433,18433,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ قَوْمٍ يُعْمَلُ فِيهِمْ بِالْمَعَاصِي هُمْ أَعَزُّ وَأَكْثَرُ مِمَّنْ يَعْمَلُهُ لَمْ يُغَيِّرُوهُ إِلَّا عَمَّهُمْ اللَّهُ بِعِقَابٍ ‏","","",""],[18434,18434,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُجَالِدُ بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَكُمْ الْمُصَدِّقُ فَلَا يُفَارِقُكُمْ إِلَّا عَنْ رِضًا ‏","","",""],[18435,18435,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏حَبْرٌ ‏ ‏بِالْيَمَنِ ‏ ‏إِنْ كَانَ صَاحِبُكُمْ نَبِيًّا فَقَدْ مَاتَ الْيَوْمَ قَالَ ‏ ‏جَرِيرٌ ‏ ‏فَمَاتَ يَوْمَ ‏ ‏الِاثْنَيْنِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18436,18436,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ اشْتَرِطْ عَلَيَّ فَأَنْتَ أَعْلَمُ بِالشَّرْطِ قَالَ ‏ ‏أُبَايِعُكَ عَلَى أَنْ تَعْبُدَ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمَ الصَّلَاةَ وَتُؤْتِيَ الزَّكَاةَ وَتَنْصَحَ الْمُسْلِمَ وَتَبْرَأَ مِنْ الْمُشْرِكِ ‏","","",""],[18437,18437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏بَالَ وَتَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ لَهُ فَقَالَ قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏كَانَ أَعْجَبَ ذَاكَ إِلَيْهِمْ أَنَّ إِسْلَامَ ‏ ‏جَرِيرٍ ‏ ‏كَانَ بَعْدَ ‏ ‏الْمَائِدَةِ ‏","","",""],[18438,18438,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ‏ ‏بَالَ قَالَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ لَهُ فَقَالَ قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏كَانَ أَعْجَبَ ذَاكَ إِلَيْهِمْ أَنَّ إِسْلَامَ ‏ ‏جَرِيرٍ ‏ ‏كَانَ بَعْدَ ‏ ‏الْمَائِدَةِ ‏","","",""],[18439,18439,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ ‏ ‏بَالَ قَالَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَصَلَّى وَسُئِلَ عَنْ ذَلِكَ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ مِثْلَ هَذَا ‏ ‏قَالَ ‏ ‏وَكَانَ يُعْجِبُهُمْ هَذَا الْحَدِيثُ مِنْ أَجْلِ أَنَّ ‏ ‏جَرِيرًا ‏ ‏كَانَ مِنْ آخِرِ مَنْ أَسْلَمَ ‏","","",""],[18440,18440,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏جَرِيرًا ‏ ‏بَالَ قَائِمًا ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ وَصَلَّى ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَذَكَرَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ فَعَلَ مِثْلَ ذَلِكَ ‏","","",""],[18441,18441,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي نُخَيْلَةَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُبَايِعُهُ فَقُلْتُ هَاتِ يَدَكَ وَاشْتَرِطْ عَلَيَّ وَأَنْتَ أَعْلَمُ بِالشَّرْطِ فَقَالَ ‏ ‏أُبَايِعُكَ عَلَى أَنْ لَا تُشْرِكَ بِاللَّهِ شَيْئًا وَتُقِيمَ الصَّلَاةَ وَتُؤْتِيَ الزَّكَاةَ وَتَنْصَحَ الْمُسْلِمَ وَتُفَارِقَ الْمُشْرِكَ ‏","","",""],[18442,18442,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَبَقَ ‏ ‏إِلَى أَرْضِ الشِّرْكِ ‏ ‏يَعْنِي الْعَبْدَ ‏ ‏فَقَدْ حَلَّ بِنَفْسِهِ وَرُبَّمَا رَفَعَهُ ‏ ‏شَرِيكٌ ‏","","",""],[18443,18443,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ هُوَ الزُّبَيْرِيُّ ‏ ‏قَالَ ثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَبَقَ ‏ ‏الْعَبْدُ إِلَى أَرْضِ الْعَدُوِّ فَقَدْ حَلَّ دَمُهُ ‏","","",""],[18444,18444,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18445,18445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عَامِرٍ الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا عَبْدٍ ‏ ‏أَبَقَ ‏ ‏فَقَدْ بَرِئَتْ مِنْهُ ‏ ‏الذِّمَّةُ ‏","","",""],[18446,18446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا عَبْدٍ ‏ ‏أَبَقَ ‏ ‏مِنْ مَوَالِيهِ فَقَدْ كَفَرَ ‏","","",""],[18447,18447,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ قَرْمٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ لَا يُرْحَمْ وَمَنْ لَا يَغْفِرْ لَا يُغْفَرْ لَهُ ‏","","",""],[18448,18448,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏","","",""],[18449,18449,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍِ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏وَعَبْدَةُ ‏ ‏قَالَ ثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَاكُمْ الْمُصَدِّقُ فَلَا يُفَارِقُكُمْ إِلَّا وَهُوَ رَاضٍ ‏","","",""],[18450,18450,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18451,18451,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏","","",""],[18452,18452,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏أَلَا تُرِيحُنِي مِنْ ‏ ‏ذِي الْخَلَصَةِ ‏ ‏بَيْتٍ ‏ ‏لِخَثْعَمَ ‏ ‏كَانَ يُعْبَدُ فِي الْجَاهِلِيَّةِ يُسَمَّى كَعْبَةَ الْيَمَانِيَةِ قَالَ فَخَرَجْنَا إِلَيْهِ فِي خَمْسِينَ وَمِائَةِ رَاكِبٍ قَالَ فَخَرَّبْنَاهُ ‏ ‏أَوْ حَرَّقْنَاهُ ‏ ‏حَتَّى تَرَكْنَاهُ كَالْجَمَلِ الْأَجْرَبِ قَالَ ثُمَّ بَعَثَ ‏ ‏جَرِيرٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَشِّرُهُ بِذَلِكَ قَالَ فَلَمَّا جَاءَهُ قَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ يَا رَسُولَ اللَّهِ مَا جِئْتُكَ حَتَّى تَرَكْنَاهُ كَالْجَمَلِ الْأَجْرَبِ قَالَ فَبَرَّكَ عَلَى ‏ ‏أَحْمَسَ ‏ ‏وَعَلَى خَيْلِهَا وَرِجَالِهَا خَمْسَ مَرَّاتٍ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي رَجُلٌ لَا أَثْبُتُ عَلَى الْخَيْلِ فَوَضَعَ يَدَهُ عَلَى وَجْهِي حَتَّى وَجَدْتُ بَرْدَهَا وَقَالَ اللَّهُمَّ اجْعَلْهُ هَادِيًا مَهْدِيًّا ‏","","",""],[18453,18453,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ ‏ ‏قَيْسٌ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏مَا حَجَبَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي قَطُّ إِلَّا تَبَسَّمَ ‏","","",""],[18454,18454,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ أَمَا ‏ ‏إِنَّكُمْ سَتُعْرَضُونَ عَلَى رَبِّكُمْ عَزَّ وَجَلَّ فَتَرَوْنَهُ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لَا ‏ ‏تُضَامُونَ ‏ ‏فَإِنْ اسْتَطَعْتُمْ أَنْ لَا ‏ ‏تُغْلَبُوا ‏ ‏عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا ثُمَّ قَرَأَ ‏ ‏فَ ‏ { ‏سَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ‏}","","",""],[18455,18455,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ وَهُوَ الضَّرِيرُ ‏ ‏قَالَ ثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هِلَالٍ الْعَبْسِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يُحْرَمْ الرِّفْقَ يُحْرَمْ الْخَيْرَ ‏","","",""],[18456,18456,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ قَوْمٍ يُعْمَلُ فِيهِمْ بِالْمَعَاصِي هُمْ أَعَزُّ مِنْهُمْ وَأَمْنَعُ لَا يُغَيِّرُونَ إِلَّا عَمَّهُمْ اللَّهُ تَعَالَى بِعِقَابِهِ ‏ ‏حَدَّثَنَاه ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنِي ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏أَظُنُّهُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَا عَمِلَ قَوْمٌ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَاه ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[18457,18457,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ هُوَ ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَلَى الْمِنْبَرِ يَقُولُ بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاشْتَرَطَ عَلَيَّ النُّصْحَ لِكُلِّ مُسْلِمٍ فَإِنِّي لَكُمْ لَنَاصِحٌ ‏","","",""],[18458,18458,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَنْصِتْ ‏ ‏النَّاسَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[18459,18459,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ ‏ ‏بَلَغَنَا ‏ ‏أَنَّ ‏ ‏جَرِيرًا ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَنْصِتْ النَّاسَ ثُمَّ قَالَ عِنْدَ ذَلِكَ ‏ ‏لَأَعْرِفَنَّ بَعْدَ مَا أَرَى تَرْجِعُونَ بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[18460,18460,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سِمَاكَ بْنَ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمِيرَةَ ‏ ‏قَالَ ‏ ‏وَكَانَ قَائِدَ ‏ ‏الْأَعْشَى ‏ ‏فِي الْجَاهِلِيَّةِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏أُبَايِعُكَ ‏ ‏عَلَى الْإِسْلَامِ قَالَ فَقَبَضَ يَدَهُ وَقَالَ ‏ ‏وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ مَنْ لَا يَرْحَمْ النَّاسَ لَمْ يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18461,18461,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18462,18462,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ صُهَيْبٍ ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يُوسُفُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَمْ يَأْخُذْ مِنْ شَارِبِهِ فَلَيْسَ مِنَّا ‏","","",""],[18463,18463,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَوْفٍ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَهْلِ ‏ ‏قُبَاءَ ‏ ‏وَهُمْ يُصَلُّونَ الضُّحَى فَقَالَ ‏ ‏صَلَاةُ الْأَوَّابِينَ إِذَا ‏ ‏رَمِضَتْ ‏ ‏الْفِصَالُ ‏ ‏مِنْ الضُّحَى ‏","","",""],[18464,18464,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّانَ التَّيْمِيِّ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ حَيَّانَ التَّيْمِيُّ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ أَنَا ‏ ‏وَحُصَيْنُ بْنُ سَبْرَةَ ‏ ‏وَعُمَرُ بْنُ مُسْلِمٍ ‏ ‏إِلَى ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏فَلَمَّا جَلَسْنَا إِلَيْهِ قَالَ لَهُ ‏ ‏حُصَيْنٌ ‏ ‏لَقَدْ لَقِيتَ يَا ‏ ‏زَيْدُ ‏ ‏خَيْرًا كَثِيرًا رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَمِعْتَ حَدِيثَهُ وَغَزَوْتَ مَعَهُ وَصَلَّيْتَ مَعَهُ لَقَدْ رَأَيْتَ يَا ‏ ‏زَيْدُ ‏ ‏خَيْرًا كَثِيرًا ‏ ‏حَدِّثْنَا ‏ ‏يَا ‏ ‏زَيْدُ ‏ ‏مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ابْنَ أَخِي وَاللَّهِ لَقَدْ كَبُرَتْ سِنِّي وَقَدُمَ عَهْدِي وَنَسِيتُ بَعْضَ الَّذِي كُنْتُ أَعِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا حَدَّثْتُكُمْ فَاقْبَلُوهُ وَمَا لَا فَلَا ‏ ‏تُكَلِّفُونِيهِ ثُمَّ قَالَ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا خَطِيبًا فِينَا بِمَاءٍ يُدْعَى ‏ ‏خُمًّا ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَحَمِدَ اللَّهَ تَعَالَى وَأَثْنَى عَلَيْهِ وَوَعَظَ وَذَكَّرَ ثُمَّ قَالَ أَمَّا بَعْدُ أَلَا يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّمَا أَنَا بَشَرٌ يُوشِكُ أَنْ يَأْتِيَنِي رَسُولُ رَبِّي عَزَّ وَجَلَّ فَأُجِيبُ وَإِنِّي تَارِكٌ فِيكُمْ ثَقَلَيْنِ أَوَّلُهُمَا كِتَابُ اللَّهِ عَزَّ وَجَلَّ فِيهِ الْهُدَى وَالنُّورُ فَخُذُوا بِكِتَابِ اللَّهِ تَعَالَى وَاسْتَمْسِكُوا بِهِ فَحَثَّ عَلَى كِتَابِ اللَّهِ وَرَغَّبَ فِيهِ قَالَ وَأَهْلُ بَيْتِي أُذَكِّرُكُمْ اللَّهَ فِي أَهْلِ بَيْتِي أُذَكِّرُكُمْ اللَّهَ فِي أَهْلِ بَيْتِي أُذَكِّرُكُمْ اللَّهَ فِي أَهْلِ بَيْتِي فَقَالَ لَهُ ‏ ‏حُصَيْنٌ ‏ ‏وَمَنْ أَهْلُ بَيْتِهِ يَا ‏ ‏زَيْدُ ‏ ‏أَلَيْسَ نِسَاؤُهُ مِنْ أَهْلِ بَيْتِهِ قَالَ إِنَّ نِسَاءَهُ مِنْ أَهْلِ بَيْتِهِ وَلَكِنَّ أَهْلَ بَيْتِهِ مَنْ حُرِمَ ‏ ‏الصَّدَقَةَ ‏ ‏بَعْدَهُ قَالَ وَمَنْ هُمْ قَالَ هُمْ آلُ ‏ ‏عَلِيٍّ ‏ ‏وَآلُ ‏ ‏عَقِيلٍ ‏ ‏وَآلُ ‏ ‏جَعْفَرٍ ‏ ‏وَآلُ ‏ ‏عَبَّاسٍ ‏ ‏قَالَ أَكُلُّ هَؤُلَاءِ حُرِمَ ‏ ‏الصَّدَقَةَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[18465,18465,"","","‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏فِي مَجْلِسِهِ ذَلِكَ ‏ ‏قَالَ ‏ ‏بَعَثَ إِلَيَّ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏فَأَتَيْتُهُ فَقَالَ مَا أَحَادِيثُ تُحَدِّثُهَا ‏ ‏وَتَرْوِيهَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَجِدُهَا فِي كِتَابِ اللَّهِ تُحَدِّثُ أَنَّ لَهُ ‏ ‏حَوْضًا ‏ ‏فِي الْجَنَّةِ قَالَ قَدْ حَدَّثَنَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوَعَدَنَاهُ قَالَ كَذَبْتَ وَلَكِنَّكَ شَيْخٌ قَدْ خَرِفْتَ قَالَ إِنِّي قَدْ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ جَهَنَّمَ وَمَا كَذَبْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18466,18466,"","","‏ ‏وَحَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏فِي مَجْلِسِهِ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ مِنْ أَهْلِ النَّارِ لَيَعْظُمُ لِلنَّارِ حَتَّى يَكُونَ الضِّرْسُ مِنْ أَضْرَاسِهِ ‏ ‏كَأُحُدٍ ‏","","",""],[18467,18467,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏سَحَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏قَالَ فَاشْتَكَى لِذَلِكَ أَيَّامًا قَالَ فَجَاءَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏إِنَّ رَجُلًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏سَحَرَكَ عَقَدَ لَكَ عُقَدًا عُقَدًا فِي بِئْرِ كَذَا وَكَذَا فَأَرْسَلَ إِلَيْهَا مَنْ يَجِيءُ بِهَا فَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَاسْتَخْرَجَهَا فَجَاءَ بِهَا فَحَلَّلَهَا قَالَ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّمَا نُشِطَ مِنْ ‏ ‏عِقَالٍ ‏ ‏فَمَا ذَكَرَ لِذَلِكَ الْيَهُودِيِّ وَلَا رَآهُ فِي وَجْهِهِ قَطُّ حَتَّى مَاتَ ‏","","",""],[18468,18468,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏مَوْلَى ‏ ‏قَرَظَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْتُمْ بِجُزْءٍ مِنْ مِائَةِ أَلْفِ جُزْءٍ مِمَّنْ يَرِدُ عَلَيَّ ‏ ‏الْحَوْضَ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏فَقُلْنَا ‏ ‏لِزَيْدٍ ‏ ‏وَكَمْ أَنْتُمْ يَوْمَئِذٍ قَالَ فَقَالَ بَيْنَ السِّتِّ مِائَةِ إِلَى السَّبْعِ مِائَةِ ‏","","",""],[18469,18469,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏أَلَسْتَ تَزْعُمُ أَنَّ أَهْلَ الْجَنَّةِ يَأْكُلُونِ فِيهَا وَيَشْرَبُونَ وَقَالَ لِأَصْحَابِهِ إِنْ أَقَرَّ لِي بِهَذِهِ خَصَمْتُهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلَى وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنَّ أَحَدَهُمْ ‏ ‏لَيُعْطَى قُوَّةَ مِائَةِ رَجُلٍ فِي الْمَطْعَمِ وَالْمَشْرَبِ وَالشَّهْوَةِ وَالْجِمَاعِ قَالَ فَقَالَ لَهُ الْيَهُودِيُّ فَإِنَّ الَّذِي يَأْكُلُ وَيَشْرَبُ تَكُونُ لَهُ الْحَاجَةُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَةُ أَحَدِهِمْ عَرَقٌ يَفِيضُ مِنْ جُلُودِهِمْ مِثْلُ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏فَإِذَا الْبَطْنُ قَدْ ‏ ‏ضَمُرَ ‏","","",""],[18470,18470,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ الشَّيْبَانِيِّ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏رَأَى قَوْمًا يُصَلُّونَ فِي مَسْجِدِ ‏ ‏قُبَاءَ ‏ ‏مِنْ الضُّحَى فَقَالَ أَمَا لَقَدْ عَلِمُوا أَنَّ الصَّلَاةَ فِي غَيْرِ هَذِهِ السَّاعَةِ أَفْضَلُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ صَلَاةَ الْأَوَّابِينَ حِينَ ‏ ‏تَرْمَضُ ‏ ‏الْفِصَالُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً وَأُنَاسٌ يُصَلُّونَ ‏","","",""],[18471,18471,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَسْتَذْكِرُهُ كَيْفَ أَخْبَرْتَنِي عَنْ لَحْمٍ أُهْدِيَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ حَرَامٌ قَالَ نَعَمْ أَهْدَى لَهُ رَجُلٌ عُضْوًا مِنْ لَحْمِ صَيْدٍ فَرَدَّهُ وَقَالَ ‏ ‏إِنَّا لَا نَأْكُلُهُ إِنَّا حُرُمٌ ‏","","",""],[18472,18472,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏كَانَ يُكَبِّرُ عَلَى جَنَائِزِنَا أَرْبَعًا وَأَنَّهُ كَبَّرَ عَلَى جِنَازَةٍ خَمْسًا ‏ ‏فَسَأَلُوهُ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُهَا ‏ ‏أَوْ كَبَّرَهَا ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18473,18473,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَمْ يَأْخُذْ مِنْ شَارِبِهِ فَلَيْسَ مِنَّا ‏","","",""],[18474,18474,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏وَالْبَرَاءَ بْنَ عَازِبٍ ‏ ‏يَقُولَانِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الذَّهَبِ ‏ ‏بِالْوَرِقِ ‏ ‏دَيْنًا ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ ‏ ‏عَنْ ‏ ‏الصَّرْفِ ‏ ‏فَقَالَ سَلْ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏فَإِنَّهُ خَيْرٌ مِنِّي وَأَعْلَمُ قَالَ سَأَلْتُ ‏ ‏زَيْدًا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏وَعَامِرُ بْنُ مُصْعَبٍ ‏ ‏سَمِعَا ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ ‏ ‏وَزَيْدَ بْنَ أَرْقَمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏وَلَمْ يَسْمَعْهُ مِنْهُ أَنَّهُ سَمِعَ ‏ ‏زَيْدًا ‏ ‏وَالْبَرَاءَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[18475,18475,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ شُبَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كَانَ الرَّجُلُ يُكَلِّمُ صَاحِبَهُ عَلَى ‏ ‏عَهْدِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْحَاجَةِ فِي الصَّلَاةِ حَتَّى نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَقُومُوا لِلَّهِ قَانِتِينَ ‏} ‏فَأُمِرْنَا بِالسُّكُوتِ ‏","","",""],[18476,18476,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏فَقُلْتُ لَهُ إِنَّ ‏ ‏خَتَنًا ‏ ‏لِي حَدَّثَنِي عَنْكَ بِحَدِيثٍ فِي شَأْنِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏يَوْمَ غَدِيرِ ‏ ‏خُمٍّ ‏ ‏فَأَنَا أُحِبُّ أَنْ أَسْمَعَهُ مِنْكَ فَقَالَ إِنَّكُمْ مَعْشَرَ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏فِيكُمْ مَا فِيكُمْ فَقُلْتُ لَهُ لَيْسَ عَلَيْكَ مِنِّي بَأْسٌ فَقَالَ نَعَمْ كُنَّا ‏ ‏بِالْجُحْفَةِ ‏ ‏فَخَرْجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْنَا ظُهْرًا وَهُوَ آخِذٌ ‏ ‏بِعَضُدِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏أَلَسْتُمْ تَعْلَمُونَ أَنِّي أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ قَالُوا بَلَى قَالَ فَمَنْ كُنْتُ مَوْلَاهُ ‏ ‏فَعَلِيٌّ ‏ ‏مَوْلَاهُ قَالَ فَقُلْتُ لَهُ هَلْ قَالَ اللَّهُمَّ وَالِ مَنْ وَالَاهُ وَعَادِ مَنْ عَادَاهُ قَالَ إِنَّمَا أُخْبِرُكَ كَمَا سَمِعْتُ ‏","","",""],[18477,18477,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏وَأَبُو الْمُنْذِرِ ‏ ‏قَالَا ثَنَا ‏ ‏يُوسُفُ بْنُ صُهَيْبٍ ‏ ‏قَالَ ‏ ‏أَبُو الْمُنْذِرِ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏حَبِيبُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏لَقَدْ كُنَّا نَقْرَأُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَانِ مِنْ ذَهَبٍ وَفِضَّةٍ لَابْتَغَى إِلَيْهِمَا آخَرَ وَلَا يَمْلَأُ بَطْنَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ وَيَتُوبُ اللَّهُ عَلَى مَنْ تَابَ ‏","","",""],[18478,18478,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏مَوْلَى ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ أَسْلَمَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[18479,18479,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَبِي ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏كَمْ غَزَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تِسْعَ عَشْرَةَ وَغَزَوْتُ مَعَهُ سَبْعَ عَشْرَةَ وَسَبَقَنِي بِغَزَاتَيْنِ ‏","","",""],[18480,18480,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سَلَّامُ بْنُ مِسْكِينٍ ‏ ‏عَنْ ‏ ‏عَائِذِ اللَّهِ الْمُجَاشِعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي دَاوُدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏أَوْ قَالُوا ‏ ‏يَا رَسُولَ اللَّهِ مَا هَذِهِ الْأَضَاحِيُّ قَالَ ‏ ‏سُنَّةُ أَبِيكُمْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالُوا مَا لَنَا مِنْهَا قَالَ بِكُلِّ شَعْرَةٍ حَسَنَةٌ قَالُوا يَا رَسُولَ اللَّهِ فَالصُّوفُ قَالَ بِكُلِّ شَعْرَةٍ مِنْ الصُّوفِ حَسَنَةٌ ‏","","",""],[18481,18481,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَمْزَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ أَسْلَمَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَأَنْكَرَ ذَلِكَ ‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[18482,18482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏لَئِنْ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ قَالَ فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ قَالَ فَحَلَفَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏أَنَّهُ لَمْ يَكُنْ شَيْءٌ مِنْ ذَلِكَ قَالَ فَلَامَنِي قَوْمِي وَقَالُوا مَا أَرَدْتَ إِلَى هَذَا قَالَ فَانْطَلَقْتُ فَنِمْتُ كَئِيبًا ‏ ‏أَوْ حَزِينًا ‏ ‏قَالَ فَأَرْسَلَ إِلَيَّ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَنْزَلَ عُذْرَكَ وَصَدَّقَكَ قَالَ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏هُمْ الَّذِينَ يَقُولُونَ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ حَتَّى يَنْفَضُّوا ‏ ‏حَتَّى بَلَغَ ‏ ‏لَئِنْ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ ‏}","","",""],[18483,18483,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذِهِ ‏ ‏الْحُشُوشَ ‏ ‏مُحْتَضَرَةٌ ‏ ‏فَإِذَا دَخَلَ أَحَدُكُمْ فَلْيَقُلْ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[18484,18484,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مَيْمُونٍ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كَانَ لِنَفَرٍ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْوَابٌ شَارِعَةٌ فِي الْمَسْجِدِ قَالَ فَقَالَ يَوْمًا سُدُّوا هَذِهِ الْأَبْوَابَ إِلَّا بَابَ ‏ ‏عَلِيٍّ ‏ ‏قَالَ فَتَكَلَّمَ فِي ذَلِكَ النَّاسُ قَالَ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمِدَ اللَّهَ تَعَالَى وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنِّي أَمَرْتُ بِسَدِّ هَذِهِ الْأَبْوَابِ إِلَّا بَابَ ‏ ‏عَلِيٍّ ‏ ‏وَقَالَ فِيهِ قَائِلُكُمْ وَإِنِّي وَاللَّهِ مَا سَدَدْتُ شَيْئًا وَلَا فَتَحْتُهُ وَلَكِنِّي أُمِرْتُ بِشَيْءٍ فَاتَّبَعْتُهُ ‏","","",""],[18485,18485,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏مَوْلَى ‏ ‏بَنِي ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏قُطْبَةَ بْنِ مَالِكٍ ‏ ‏عَمِّ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ ‏ ‏نَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏مِنْ ‏ ‏عَلِيٍّ ‏ ‏فَقَالَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏قَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْهَى عَنْ سَبِّ الْمَوْتَى فَلِمَ تَسُبُّ ‏ ‏عَلِيًّا ‏ ‏وَقَدْ مَاتَ ‏","","",""],[18486,18486,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَبْدِ اللَّهِ مَيْمُونًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُمْ أَنْ يَتَدَاوَوْا مِنْ ذَاتِ الْجَنْبِ بِالْعُودِ الْهِنْدِيِّ وَالزَّيْتِ ‏","","",""],[18487,18487,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الشَّامِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَخْطُبُ يَقُولُ يَا أَهْلَ ‏ ‏الشَّامِ ‏ ‏حَدَّثَنِي الْأَنْصَارِيُّ قَالَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏يَعْنِي ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ وَإِنِّي لَأَرْجُو أَنْ تَكُونُوا هُمْ يَا أَهْلَ ‏ ‏الشَّامِ ‏","","",""],[18488,18488,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَمْزَةَ ‏ ‏مَوْلَى ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَنْزِلٍ نَزَلُوهُ فِي مَسِيرِهِ فَقَالَ ‏ ‏مَا أَنْتُمْ بِجُزْءٍ مِنْ مِائَةِ أَلْفِ جُزْءٍ مِمَّنْ يَرِدُ عَلَيَّ ‏ ‏الْحَوْضَ ‏ ‏مِنْ أُمَّتِي ‏ ‏قَالَ ‏ ‏قُلْتُ كَمْ كُنْتُمْ يَوْمَئِذٍ قَالَ كُنَّا سَبْعَ مِائَةٍ ‏ ‏أَوْ ثَمَانِ مِائَةٍ ‏","","",""],[18489,18489,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّضْرَ بْنَ أَنَسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏","","",""],[18490,18490,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏دَاوُدَ الطُّفَاوِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مُسْلِمٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي ‏ ‏دُبُرِ ‏ ‏صَلَاتِهِ ‏ ‏اللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ أَنَا شَهِيدٌ أَنَّكَ أَنْتَ الرَّبُّ وَحْدَكَ لَا شَرِيكَ لَكَ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مَرَّتَيْنِ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ ‏ ‏أَنَا شَهِيدٌ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُكَ وَرَسُولُكَ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ أَنَا شَهِيدٌ أَنَّ الْعِبَادَ كُلَّهُمْ إِخْوَةٌ اللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ اجْعَلْنِي مُخْلِصًا لَكَ وَأَهْلِي فِي كُلِّ سَاعَةٍ مِنْ الدُّنْيَا وَالْآخِرَةِ ذَا الْجِلَالِ وَالْإِكْرَامِ اسْمَعْ وَاسْتَجِبْ اللَّهُ الْأَكْبَرُ الْأَكْبَرُ اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ اللَّهُ الْأَكْبَرُ الْأَكْبَرُ ‏ ‏حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ اللَّهُ الْأَكْبَرُ الْأَكْبَرُ ‏","","",""],[18491,18491,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَمُؤَمَّلٌ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏يَا ‏ ‏زَيْدُ بْنَ أَرْقَمَ ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُهْدِيَ لَهُ عُضْوُ صَيْدٍ وَهُوَ مُحْرِمٌ ‏ ‏فَلَمْ يَقْبَلْهُ قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏فَرَدَّهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ إِنَّا حُرُمٌ قَالَ نَعَمْ ‏","","",""],[18492,18492,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏قَالَ ‏ ‏لَمَّا قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏مَا قَالَ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ أَوْ قَالَ لَئِنْ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَسَمِعْتُهُ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ قَالَ فَلَامَنِي نَاسٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ وَجَاءَ هُوَ فَحَلَفَ مَا قَالَ ذَاكَ فَرَجَعْتُ إِلَى الْمَنْزِلِ فَنِمْتُ قَالَ فَأَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ بَلَغَنِي فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ صَدَّقَكَ وَعَذَرَكَ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏هُمْ الَّذِينَ يَقُولُونَ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ ‏} ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[18493,18493,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏كَمْ غَزَوْتَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَبْعَ عَشْرَةَ قَالَ وَحَدَّثَنِي ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَا تِسْعَ عَشْرَةَ وَأَنَّهُ حَجَّ بَعْدَ مَا هَاجَرَ حَجَّةً وَاحِدَةً حَجَّةَ الْوَدَاعِ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏وَبِمَكَّةَ ‏ ‏أُخْرَى ‏","","",""],[18494,18494,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏كَتَبَ إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏زَمَنَ ‏ ‏الْحَرَّةِ ‏ ‏يُعَزِّيهِ فِيمَنْ قُتِلَ مِنْ وَلَدِهِ وَقَوْمِهِ وَقَالَ أُبَشِّرُكَ بِبُشْرَى مِنْ اللَّهِ عَزَّ وَجَلَّ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَاغْفِرْ لِنِسَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِنِسَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِنِسَاءِ أَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏","","",""],[18495,18495,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏عَلَى جِنَازَةٍ فَكَبَّرَ خَمْسًا فَقَامَ إِلَيْهِ ‏ ‏أَبُو عِيسَى عَبْدُ الرَّحْمَنِ بْنُ أَبِي لَيْلَى ‏ ‏فَأَخَذَ بِيَدِهِ فَقَالَ نَسِيتَ قَالَ لَا وَلَكِنْ صَلَّيْتُ خَلْفَ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏خَلِيلِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَبَّرَ خَمْسًا فَلَا أَتْرُكُهَا أَبَدًا ‏","","",""],[18496,18496,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلْمَانَ الْمُؤَذِّنِ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ ‏ ‏أَبُو سَرِيحَةَ ‏ ‏فَصَلَّى عَلَيْهِ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏فَكَبَّرَ عَلَيْهِ أَرْبَعًا وَقَالَ كَذَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18497,18497,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا ثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏جَمَعَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏النَّاسَ فِي ‏ ‏الرَّحَبَةِ ‏ ‏ثُمَّ قَالَ لَهُمْ أَنْشُدُ اللَّهَ كُلَّ امْرِئٍ مُسْلِمٍ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَوْمَ ‏ ‏غَدِيرِ خُمٍّ ‏ ‏مَا سَمِعَ لَمَّا قَامَ فَقَامَ ثَلَاثُونَ مِنْ النَّاسِ ‏ ‏وَقَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏فَقَامَ نَاسٌ كَثِيرٌ ‏ ‏فَشَهِدُوا حِينَ أَخَذَهُ بِيَدِهِ فَقَالَ لِلنَّاسِ أَتَعْلَمُونَ أَنِّي أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَنْ كُنْتُ ‏ ‏مَوْلَاهُ ‏ ‏فَهَذَا ‏ ‏مَوْلَاهُ ‏ ‏اللَّهُمَّ ‏ ‏وَالِ ‏ ‏مَنْ ‏ ‏وَالَاهُ ‏ ‏وَعَادِ مَنْ عَادَاهُ ‏ ‏قَالَ ‏ ‏فَخَرَجْتُ وَكَأَنَّ فِي نَفْسِي شَيْئًا فَلَقِيتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏فَقُلْتُ لَهُ إِنِّي سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏يَقُولُ كَذَا وَكَذَا قَالَ فَمَا تُنْكِرُ قَدْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ذَلِكَ لَهُ ‏","","",""],[18498,18498,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَمْزَةَ ‏ ‏رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏يَقُولُ ‏ ‏أَوَّلُ مَنْ أَسْلَمَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَأَنْكَرَهُ ‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[18499,18499,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي لَيْلَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا جِئْنَاهُ قُلْنَا حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّا قَدْ ‏ ‏كَبُرْنَا وَنَسِينَا وَالْحَدِيثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَدِيدٌ ‏","","",""],[18500,18500,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏قُلْنَا ‏ ‏لِزَيْدِ بْنِ أَرْقَمَ ‏ ‏حَدِّثْنَا قَالَ ‏ ‏كَبُرْنَا وَنَسِينَا وَالْحَدِيثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَدِيدٌ ‏","","",""],[18501,18501,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ أَسْلَمَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِلنَّخَعِيِّ ‏ ‏فَأَنْكَرَهُ وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَوَّلُ مَنْ أَسْلَمَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18502,18502,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ نَافِعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ دِينَارٍ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏وَالْبَرَاءَ بْنَ عَازِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏كَانَا شَرِيكَيْنِ فَاشْتَرَيَا فِضَّةً بِنَقْدٍ ‏ ‏وَنَسِيئَةً ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمَا أَنَّ ‏ ‏مَا كَانَ بِنَقْدٍ فَأَجِيزُوهُ وَمَا كَانَ ‏ ‏بِنَسِيئَةٍ ‏ ‏فَرُدُّوهُ ‏","","",""],[18503,18503,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْجُبْنِ وَالْبُخْلِ وَعَذَابِ الْقَبْرِ اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا ‏ ‏وَزَكِّهَا ‏ ‏أَنْتَ خَيْرُ مَنْ ‏ ‏زَكَّاهَا ‏ ‏أَنْتَ ‏ ‏وَلِيُّهَا ‏ ‏وَمَوْلَاهَا ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ قَلْبٍ لَا يَخْشَعُ وَنَفَسٍ لَا تَشْبَعُ وَعِلْمٍ لَا يَنْفَعُ وَدَعْوَةٍ لَا يُسْتَجَابُ لَهَا قَالَ فَقَالَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَاهُنَّ وَنَحْنُ ‏ ‏نُعَلِّمُكُمُوهُنَّ ‏","","",""],[18504,18504,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا حَمْزَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَنَزَلْنَا مَنْزِلًا فَسَمِعْتُهُ يَقُولُ ‏ ‏مَا أَنْتُمْ بِجُزْءٍ مِنْ مِائَةِ أَلْفِ جُزْءٍ مِمَّنْ يَرِدُ عَلَيَّ ‏ ‏الْحَوْضَ ‏ ‏مِنْ أُمَّتِي ‏ ‏قَالَ ‏ ‏كَمْ كُنْتُمْ يَوْمَئِذٍ قَالَ سَبْعَ مِائَةٍ ‏ ‏أَوْ ثَمَانِ مِائَةٍ ‏","","",""],[18505,18505,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏وَزَيْدَ بْنَ أَرْقَمَ ‏ ‏عَنْ الصَّرْفِ ‏ ‏فَهَذَا يَقُولُ سَلْ هَذَا فَإِنَّهُ خَيْرٌ مِنِّي وَأَعْلَمُ وَهَذَا يَقُولُ سَلْ هَذَا فَهُوَ خَيْرٌ مِنِّي وَأَعْلَمُ ‏ ‏قَالَ فَسَأَلْتُهُمَا فَكِلَاهُمَا يَقُولُ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَرِقِ ‏ ‏بِالذَّهَبِ دَيْنًا وَسَأَلْتُ هَذَا فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْوَرِقِ بِالذَّهَبِ دَيْنًا ‏","","",""],[18506,18506,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏يَا ‏ ‏زَيْدُ بْنَ أَرْقَمَ ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُهْدِيَ لَهُ عُضْوُ صَيْدٍ وَهُوَ مُحْرِمٌ فَلَمْ يَقْبَلْهُ قَالَ بَلَى ‏","","",""],[18507,18507,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرٌ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ حَكِيمٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏عَلَى جِنَازَةٍ ‏ ‏فَكَبَّرَ خَمْسًا ثُمَّ الْتَفَتَ فَقَالَ هَكَذَا كَبَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18508,18508,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبِيعَةَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏وَهُوَ دَاخِلٌ عَلَى ‏ ‏الْمُخْتَارِ ‏ ‏أَوْ خَارِجٌ مِنْ عِنْدِهِ ‏ ‏فَقُلْتُ لَهُ أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي تَارِكٌ فِيكُمْ ‏ ‏الثَّقَلَيْنِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[18509,18509,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عُقْبَةَ الْمُحَلِّمِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ مِنْ أَهْلِ الْجَنَّةِ يُعْطَى قُوَّةَ مِائَةِ رَجُلٍ فِي الْأَكْلِ وَالشُّرْبِ وَالشَّهْوَةِ وَالْجِمَاعِ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَإِنَّ الَّذِي يَأْكُلُ وَيَشْرَبُ تَكُونُ لَهُ ‏ ‏الْحَاجَةُ ‏ ‏قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَةُ ‏ ‏أَحَدِهِمْ عَرَقٌ يَفِيضُ مِنْ جِلْدِهِ فَإِذَا بَطْنُهُ قَدْ ‏ ‏ضَمُرَ ‏","","",""],[18510,18510,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏مَوْلَى ‏ ‏لِبَنِي ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏قُطْبَةَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَبَّ أَمِيرٌ مِنْ الْأُمَرَاءِ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَامَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏فَقَالَ أَمَا أَنْ قَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ سَبِّ الْمَوْتَى فَلِمَ تَسُبُّ ‏ ‏عَلِيًّا ‏ ‏وَقَدْ مَاتَ ‏","","",""],[18511,18511,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَبِي ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏كَمْ ‏ ‏غَزَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تِسْعَ عَشْرَةَ وَغَزَوْتُ مَعَهُ سَبْعَ عَشْرَةَ غَزْوَةً وَسَبَقَنِي بِغَزَاتَيْنِ ‏","","",""],[18512,18512,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏وَعَامِرُ بْنُ مُصْعَبٍ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏يَقُولُ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏وَزَيْدَ بْنَ أَرْقَمَ ‏ ‏فَقَالَا كُنَّا تَاجِرَيْنِ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الصَّرْفِ ‏ ‏فَقَالَ ‏ ‏إِنْ كَانَ يَدًا بِيَدٍ فَلَا بَأْسَ وَإِنْ كَانَ ‏ ‏نَسِيئَةً ‏ ‏فَلَا يَصْلُحُ ‏","","",""],[18513,18513,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ أَبِي رَمْلَةَ الشَّامِيِّ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏سَأَلَ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِيدَيْنِ اجْتَمَعَا قَالَ نَعَمْ ‏ ‏صَلَّى الْعِيدَ أَوَّلَ النَّهَارِ ثُمَّ رَخَّصَ فِي الْجُمُعَةِ فَقَالَ مَنْ شَاءَ أَنْ يُجَمِّعَ فَلْيُجَمِّعْ ‏","","",""],[18514,18514,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ الشَّيْبَانِيِّ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏رَأَى نَاسًا يُصَلُّونَ فِي مَسْجِدِ ‏ ‏قُبَاءَ ‏ ‏مِنْ الضُّحَى فَقَالَ أَمَا لَقَدْ عَلِمُوا أَنَّ الصَّلَاةَ فِي غَيْرِ السَّاعَةِ أَفْضَلُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ صَلَاةَ ‏ ‏الْأَوَّابِينَ ‏ ‏حِينَ ‏ ‏تَرْمَضُ ‏ ‏الْفِصَالُ ‏","","",""],[18515,18515,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏زَيْدٌ ‏ ‏يُكَبِّرُ عَلَى جَنَائِزِنَا أَرْبَعًا وَأَنَّهُ كَبَّرَ عَلَى جِنَازَةٍ خَمْسًا فَسَأَلْتُهُ فَقَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُهَا ‏","","",""],[18516,18516,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْتُمْ جُزْءٌ مِنْ مِائَةِ أَلْفٍ ‏ ‏أَوْ مِنْ سَبْعِينَ أَلْفًا ‏ ‏مِمَّنْ يَرِدُ عَلَيَّ ‏ ‏الْحَوْضَ ‏ ‏قَالَ ‏ ‏فَسَأَلُوهُ كَمْ كُنْتُمْ فَقَالَ ثَمَانِ مِائَةٍ ‏ ‏أَوْ سَبْعَ مِائَةٍ ‏","","",""],[18517,18517,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18518,18518,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏قُلْنَا ‏ ‏لِزَيْدِ بْنِ أَرْقَمَ ‏ ‏حَدِّثْنَا قَالَ ‏ ‏كَبُرْنَا وَنَسِينَا وَالْحَدِيثُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَدِيدٌ ‏","","",""],[18519,18519,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏مَيْمُونٍ أَبِي عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏وَأَنَا أَسْمَعُ ‏ ‏نَزَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَادٍ يُقَالُ لَهُ ‏ ‏وَادِي خُمٍّ ‏ ‏فَأَمَرَ بِالصَّلَاةِ فَصَلَّاهَا ‏ ‏بِهَجِيرٍ ‏ ‏قَالَ فَخَطَبَنَا وَظُلِّلَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَوْبٍ عَلَى شَجَرَةِ ‏ ‏سَمُرَةٍ ‏ ‏مِنْ الشَّمْسِ فَقَالَ أَلَسْتُمْ تَعْلَمُونَ ‏ ‏أَوَلَسْتُمْ تَشْهَدُونَ ‏ ‏أَنِّي أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ قَالُوا بَلَى قَالَ فَمَنْ كُنْتُ مَوْلَاهُ فَإِنَّ ‏ ‏عَلِيًّا ‏ ‏مَوْلَاهُ اللَّهُمَّ عَادِ مَنْ عَادَاهُ وَوَالِ مَنْ وَالَاهُ ‏","","",""],[18520,18520,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏وَزَيْدَ بْنَ أَرْقَمَ ‏ ‏قَالَ سَأَلْتُ هَذَا فَقَالَ ائْتِ فُلَانًا فَإِنَّهُ خَيْرٌ مِنِّي وَأَعْلَمُ وَسَأَلْتُ الْآخَرَ فَقَالَ مِثْلَ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَرِقِ ‏ ‏بِالذَّهَبِ دَيْنًا ‏","","",""],[18521,18521,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْعَتُ ‏ ‏الزَّيْتَ ‏ ‏وَالْوَرْسَ ‏ ‏مِنْ ‏ ‏ذَاتِ الْجَنْبِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏يَلُدُّهُ ‏ ‏مِنْ جَانِبِهِ الَّذِي ‏ ‏يَشْتَكِيهِ ‏","","",""],[18522,18522,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَيْمُونٍ أَبِي عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏فَجَاءَ رَجُلٌ مِنْ أَقْصَى ‏ ‏الْفَسْطَاسِ ‏ ‏فَسَأَلَهُ عَنْ دَاءٍ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَلَسْتُ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ قَالُوا بَلَى قَالَ ‏ ‏مَنْ كُنْتُ مَوْلَاهُ ‏ ‏فَعَلِيٌّ ‏ ‏مَوْلَاهُ ‏ ‏قَالَ ‏ ‏مَيْمُونٌ ‏ ‏فَحَدَّثَنِي ‏ ‏بَعْضُ الْقَوْمِ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏أَنَّ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ وَالِ مَنْ وَالَاهُ وَعَادِ مَنْ عَادَاهُ ‏","","",""],[18523,18523,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَجْلَحَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏بِالْيَمَنِ ‏ ‏فَأُتِيَ بِامْرَأَةٍ ‏ ‏وَطِئَهَا ‏ ‏ثَلَاثَةُ نَفَرٍ فِي طُهْرٍ وَاحِدٍ فَسَأَلَ اثْنَيْنِ أَتُقِرَّانِ لِهَذَا بِالْوَلَدِ فَلَمْ يُقِرَّا ثُمَّ سَأَلَ اثْنَيْنِ أَتُقِرَّانِ لِهَذَا بِالْوَلَدِ فَلَمْ يُقِرَّا ثُمَّ سَأَلَ اثْنَيْنِ حَتَّى فَرَغَ يَسْأَلُ اثْنَيْنِ اثْنَيْنِ عَنْ وَاحِدٍ فَلَمْ يُقِرُّوا ثُمَّ أَقْرَعَ بَيْنَهُمْ فَأَلْزَمَ الْوَلَدَ الَّذِي خَرَجَتْ عَلَيْهِ الْقُرْعَةُ وَجَعَلَ عَلَيْهِ ثُلُثَيْ الدِّيَةِ فَرُفِعَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏","","",""],[18524,18524,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏وَلَمْ يَسْمَعْهُ مِنْهُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏وَالْبَرَاءَ بْنَ عَازِبٍ ‏ ‏يَقُولَانِ ‏ ‏سَمِعْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي ‏ ‏الصَّرْفِ ‏ ‏إِذَا كَانَ يَدًا بِيَدٍ فَلَا بَأْسَ إِذَا كَانَ دَيْنًا فَلَا يَصْلُحُ ‏","","",""],[18525,18525,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ ‏ ‏الْحُشُوشَ ‏ ‏مُحْتَضَرَةٌ ‏ ‏فَإِذَا أَرَادَ أَحَدُكُمْ أَنْ يَدْخُلَ فَلْيَقُلْ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[18526,18526,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ هَذِهِ ‏ ‏الْحُشُوشَ ‏ ‏مُحْتَضَرَةٌ ‏ ‏فَإِذَا دَخَلَ أَحَدُكُمْ الْخَلَاءَ فَلْيَقُلْ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[18527,18527,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَيَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي بُكَيْرٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ عَمِّي فِي غَزَاةٍ فَسَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أُبَيٍّ ابْنِ سَلُولَ ‏ ‏يَقُولُ لِأَصْحَابِهِ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ وَلَئِنْ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ فَذَكَرْتُ ذَلِكَ لِعَمِّي فَذَكَرَهُ عَمِّي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلَ إِلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثْتُهُ فَأَرْسَلَ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أُبَيِّ ابْنِ سَلُولَ ‏ ‏وَأَصْحَابِهِ فَحَلَفُوا مَا قَالُوا فَكَذَّبَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَدَّقَهُ فَأَصَابَنِي هَمٌّ لَمْ يُصِيبُنِي مِثْلُهُ قَطُّ وَجَلَسْتُ فِي الْبَيْتِ فَقَالَ عَمِّي مَا أَرَدْتَ إِلَى أَنْ كَذَّبَكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَقَتَكَ ‏ ‏قَالَ حَتَّى أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِذَا جَاءَكَ الْمُنَافِقُونَ ‏} ‏قَالَ فَبَعَثَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَهَا ثُمَّ قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ صَدَّقَكَ ‏","","",""],[18528,18528,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏يَقُولُ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَأَصَابَ النَّاسَ شِدَّةٌ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏لِأَصْحَابِهِ لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ حَتَّى ‏ ‏يَنْفَضُّوا ‏ ‏مِنْ حَوْلِهِ وَقَالَ لَئِنْ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِذَلِكَ فَأَرْسَلَ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أُبَيٍّ ‏ ‏فَسَأَلَهُ فَاجْتَهَدَ يَمِينَهُ مَا فَعَلَ فَقَالُوا كَذَّبَ ‏ ‏زَيْدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَوَقَعَ فِي نَفْسِي مِمَّا قَالُوا حَتَّى أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ تَصْدِيقِي فِي ‏ { ‏إِذَا جَاءَكَ الْمُنَافِقُونَ ‏} ‏قَالَ وَدَعَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَسْتَغْفِرَ لَهُمْ فَلَوَّوْا رُءُوسَهُمْ وَقَوْلُهُ تَعَالَى ‏ { ‏كَأَنَّهُمْ خُشُبٌ مُسَنَّدَةٌ ‏} ‏قَالَ كَانُوا رِجَالًا أَجْمَلَ شَيْءٍ ‏","","",""],[18529,18529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏فَقُلْتُ لَهُ كَمْ غَزَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تِسْعَ عَشْرَةَ قُلْتُ كَمْ غَزَوْتَ أَنْتَ مَعَهُ قَالَ سَبْعَ عَشْرَةَ غَزْوَةً قَالَ فَقُلْتُ فَمَا أَوَّلُ غَزْوَةٍ غَزَا قَالَ ‏ ‏ذَاتُ الْعُشَيْرِ ‏ ‏أَوْ ‏ ‏الْعُشَيْرَةِ ‏","","",""],[18530,18530,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَمْزَةَ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ لِكُلِّ نَبِيٍّ أَتْبَاعًا وَإِنَّا قَدْ تَبِعْنَاكَ فَادْعُ اللَّهَ عَزَّ وَجَلَّ أَنْ يَجْعَلَ أَتْبَاعَنَا مِنَّا قَالَ ‏ ‏فَدَعَا لَهُمْ أَنْ يَجْعَلَ أَتْبَاعَهُمْ مِنْهُمْ ‏ ‏قَالَ ‏ ‏فَنَمَّيْتُ ذَلِكَ إِلَى ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏فَقَالَ ‏ ‏زَعَمَ ذَلِكَ ‏ ‏زَيْدٌ يَعْنِي ابْنَ أَرْقَمَ ‏","","",""],[18531,18531,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏مَاتَ ‏ ‏لِأَنَسٍ ‏ ‏وَلَدٌ فَكَتَبَ إِلَيْهِ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏","","",""],[18532,18532,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏عَنْ ‏ ‏الصَّرْفِ ‏ ‏فَقَالَ سَلْ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏فَإِنَّهُ خَيْرٌ مِنِّي وَأَعْلَمُ قَالَ فَسَأَلْتُ ‏ ‏زَيْدًا ‏ ‏فَقَالَ سَلْ ‏ ‏الْبَرَاءَ ‏ ‏فَإِنَّهُ خَيْرٌ مِنِّي وَأَعْلَمُ ‏ ‏قَالَ فَقَالَا ‏ ‏جَمِيعًا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَرِقِ ‏ ‏بِالذَّهَبِ دَيْنًا ‏","","",""],[18533,18533,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَيْمُونٍ أَبِي عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏قَالَ ‏ ‏غَزَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعَ عَشْرَةَ غَزْوَةً وَغَزَوْتُ مَعَهُ سَبْعَ عَشْرَةَ غَزْوَةً ‏","","",""],[18534,18534,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏قَالَ ‏ ‏شَكَّ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏فِي ‏ ‏الْحَوْضِ ‏ ‏فَأَرْسَلَ إِلَى ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏فَسَأَلَهُ عَنْ ‏ ‏الْحَوْضِ ‏ ‏فَحَدَّثَهُ حَدِيثًا ‏ ‏مُوَنَّقًا ‏ ‏أَعْجَبَهُ فَقَالَ لَهُ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا وَلَكِنْ ‏ ‏حَدَّثَنِيهِ ‏ ‏أَخِي ‏","","",""],[18535,18535,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏فَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَسْتَذْكِرُهُ كَيْفَ أَخْبَرْتَنِي عَنْ لَحْمٍ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أُهْدِيَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَامًا ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أُهْدِيَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ أُهْدِيَ لَهُ عُضْوٌ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏رِجْلُ عُضْوٍ ‏ ‏مِنْ لَحْمِ صَيْدٍ فَرَدَّهُ عَلَيْهِ وَقَالَ إِنَّا ‏ ‏لَا نَأْكُلُهُ إِنَّا حُرُمٌ ‏","","",""],[18536,18536,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَجْلَحَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ نَفَرًا ‏ ‏وَطِئُوا ‏ ‏امْرَأَةً فِي طُهْرٍ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏لِاثْنَيْنِ مِنْهُمْ أَتَطِيبَانِ نَفْسًا لِذَا فَقَالَا لَا فَأَقْبَلَ عَلَى الْآخَرَيْنِ فَقَالَ أَتَطِيبَانِ نَفْسًا لِذَا فَقَالَا لَا قَالَ أَنْتُمْ شُرَكَاءُ ‏ ‏مُتَشَاكِسُونَ ‏ ‏قَالَ إِنِّي مُقْرِعٌ بَيْنَكُمْ فَأَيُّكُمْ قُرِعَ أَغْرَمْتُهُ ثُلُثَيْ الدِّيَةِ وَأَلْزَمْتُهُ الْوَلَدَ قَالَ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا أَعْلَمُ إِلَّا مَا قَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[18537,18537,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏يُعَزِّيهِ بِمَنْ أُصِيبَ مِنْ وَلَدِهِ وَقَوْمِهِ يَوْمَ ‏ ‏الْحَرَّةِ ‏ ‏فَكَتَبَ إِلَيْهِ وَأُبَشِّرُكَ بِبُشْرَى مِنْ اللَّهِ عَزَّ وَجَلَّ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِأَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِنِسَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِنِسَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏ ‏وَلِنِسَاءِ أَبْنَاءِ أَبْنَاءِ ‏ ‏الْأَنْصَارِ ‏","","",""],[18538,18538,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَجْلَحُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْخَلِيلِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أُتِيَ فِي ثَلَاثَةِ نَفَرٍ إِذْ كَانَ ‏ ‏بِالْيَمَنِ ‏ ‏اشْتَرَكُوا فِي وَلَدٍ فَأَقْرَعَ بَيْنَهُمْ فَضَمِنَ الَّذِي أَصَابَتْهُ الْقُرْعَةُ ثُلُثَيْ الدِّيَةِ وَجَعَلَ الْوَلَدَ لَهُ قَالَ ‏ ‏زَيْدُ بْنُ أَرْقَمَ ‏ ‏فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِقَضَاءِ ‏ ‏عَلِيٍّ ‏ ‏فَضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏","","",""],[18539,18539,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدٍ أَبِي الْعَلَاءِ الْخَفَّافِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ أَنْعَمُ وَصَاحِبُ ‏ ‏الْقَرْنِ ‏ ‏قَدْ ‏ ‏الْتَقَمَ ‏ ‏الْقَرْنَ ‏ ‏وَحَنَى جَبْهَتَهُ وَأَصْغَى السَّمْعَ مَتَى يُؤْمَرُ قَالَ فَسَمِعَ ذَلِكَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَقَّ عَلَيْهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا ‏ ‏حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ طَهْمَانَ أَبُو الْعَلَاءِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[18540,18540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى مَسْجِدِ ‏ ‏قُبَاءَ ‏ ‏أَوْ دَخَلَ مَسْجِدَ ‏ ‏قُبَاءَ ‏ ‏بَعْدَمَا أَشْرَقَتْ الشَّمْسُ فَإِذَا هُمْ يُصَلُّونَ فَقَالَ ‏ ‏إِنَّ ‏ ‏صَلَاةَ ‏ ‏الْأَوَّابِينَ ‏ ‏كَانُوا يُصَلُّونَهَا إِذَا ‏ ‏رَمِضَتْ ‏ ‏الْفِصَالُ ‏","","",""],[18541,18541,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ أَبِي إِسْحَاقَ ‏ ‏وَإِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏أَصَابَنِي رَمَدٌ ‏ ‏فَعَادَنِي ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا بَرَأْتُ خَرَجْتُ قَالَ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ لَوْ كَانَتْ عَيْنَاكَ لِمَا بِهِمَا مَا كُنْتَ صَانِعًا قَالَ قُلْتُ لَوْ كَانَتَا عَيْنَايَ لِمَا بِهِمَا صَبَرْتُ وَاحْتَسَبْتُ قَالَ ‏ ‏لَوْ كَانَتْ عَيْنَاكَ لِمَا بِهِمَا ثُمَّ صَبَرْتَ وَاحْتَسَبْتَ لَلَقِيتَ اللَّهَ عَزَّ وَجَلَّ وَلَا ذَنْبَ لَكَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏ثُمَّ صَبَرْتَ وَاحْتَسَبْتَ لَأَوْجَبَ اللَّهُ تَعَالَى لَكَ الْجَنَّةَ ‏","","",""],[18542,18542,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَبْدِ اللَّهِ بْنِ مُعَاوِيَةَ بْنِ عَاصِمِ بْنِ الْمُنْذِرِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامٌ أَبُو الْمُنْذِرِ الْقَارِئُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَوْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا مَثَلُ الْمُسْلِمِينَ كَالرَّجُلِ الْوَاحِدِ إِذَا وَجِعَ مِنْهُ شَيْءٌ تَدَاعَى لَهُ سَائِرُ جَسَدِهِ ‏","","",""],[18543,18543,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو وَكِيعٍ الْجَرَّاحُ بْنُ مَلِيحٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏مَنْ لَمْ يَشْكُرْ الْقَلِيلَ لَمْ يَشْكُرْ الْكَثِيرَ وَمَنْ لَمْ يَشْكُرْ النَّاسَ لَمْ يَشْكُرْ اللَّهَ عَزَّ وَجَلَّ وَالتَّحَدُّثُ بِنِعْمَةِ اللَّهِ شُكْرٌ وَتَرْكُهَا كُفْرٌ وَالْجَمَاعَةُ رَحْمَةٌ وَالْفُرْقَةُ عَذَابٌ ‏","","",""],[18544,18544,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ عَبْدِ رَبِّهِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو وَكِيعٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذِهِ الْأَعْوَادِ ‏ ‏أَوْ عَلَى هَذَا الْمِنْبَرِ ‏ ‏مَنْ لَمْ يَشْكُرْ الْقَلِيلَ لَمْ يَشْكُرْ الْكَثِيرَ وَمَنْ لَمْ يَشْكُرْ النَّاسَ لَمْ يَشْكُرْ اللَّهَ عَزَّ وَجَلَّ وَالتَّحَدُّثُ بِنِعْمَةِ اللَّهِ شُكْرٌ وَتَرْكُهَا كُفْرٌ وَالْجَمَاعَةُ رَحْمَةٌ وَالْفُرْقَةُ عَذَابٌ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو أُمَامَةَ الْبَاهِلِيُّ ‏ ‏عَلَيْكُمْ بِالسَّوَادِ الْأَعْظَمِ قَالَ فَقَالَ رَجُلٌ مَا السَّوَادُ الْأَعْظَمُ فَنَادَى ‏ ‏أَبُو أُمَامَةَ ‏ ‏هَذِهِ الْآيَةَ الَّتِي فِي سُورَةِ ‏ ‏النُّورِ ‏ { ‏فَإِنْ ‏ ‏تَوَلَّوْا ‏ ‏فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ ‏}","","",""],[18545,18545,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ هُوَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاجِبُ بْنُ الْمُفَضَّلِ يَعْنِي ابْنَ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَارِبُوا بَيْنَ أَبْنَائِكُمْ ‏ ‏يَعْنِي سَوُّوا بَيْنَهُمْ ‏","","",""],[18546,18546,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ الْحَسَنِ الْبَاهِلِيُّ ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏قَالُوا ثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَاجِبِ بْنِ الْمُفَضَّلِ بْنِ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْدِلُوا بَيْنَ أَبْنَائِكُمْ اعْدِلُوا بَيْنَ أَبْنَائِكُمْ ‏","","",""],[18547,18547,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ الْبَارِقِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ وَالْأَجْرُ وَالْمَغْنَمُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[18548,18548,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنَا ‏ ‏الْبَارِقِيُّ شَبِيبٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ الْبَارِقِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ ‏ ‏وَرَأَيْتُ فِي دَارِهِ سَبْعِينَ فَرَسًا ‏","","",""],[18549,18549,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏شَبِيبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْحَيَّ ‏ ‏يُخْبِرُونَ عَنْ ‏ ‏عُرْوَةَ الْبَارِقِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ مَعَهُ بِدِينَارٍ يَشْتَرِي لَهُ أُضْحِيَّةً ‏ ‏وَقَالَ مَرَّةً ‏ ‏أَوْ شَاةً ‏ ‏فَاشْتَرَى لَهُ اثْنَتَيْنِ فَبَاعَ وَاحِدَةً بِدِينَارٍ وَأَتَاهُ بِالْأُخْرَى فَدَعَا لَهُ بِالْبَرَكَةِ فِي بَيْعِهِ ‏ ‏فَكَانَ لَوْ اشْتَرَى التُّرَابَ لَرَبِحَ فِيهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ ‏ ‏كُلُّهُمْ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي الْجَعْدِ ‏","","",""],[18550,18550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ الْأَجْرُ وَالْمَغْنَمُ ‏","","",""],[18551,18551,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏ابْنِ أَبِي الْجَعْدِ الْبَارِقِيُّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ الْأَجْرُ وَالْمَغْنَمُ ‏","","",""],[18552,18552,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ جَعْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ ‏","","",""],[18553,18553,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ الْأَجْرُ وَالْمَغْنَمُ ‏","","",""],[18554,18554,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرُ بْنُ الْخِرِّيتِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو لَبِيدٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ الْبَارِقِيِّ ‏ ‏قَالَ ‏ ‏عَرَضَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَلَبٌ ‏ ‏فَأَعْطَانِي دِينَارًا وَقَالَ أَيْ ‏ ‏عُرْوَةُ ‏ ‏ائْتِ ‏ ‏الْجَلَبَ ‏ ‏فَاشْتَرِ لَنَا شَاةً فَأَتَيْتُ ‏ ‏الْجَلَبَ ‏ ‏فَسَاوَمْتُ صَاحِبَهُ فَاشْتَرَيْتُ مِنْهُ شَاتَيْنِ بِدِينَارٍ فَجِئْتُ أَسُوقُهُمَا ‏ ‏أَوْ قَالَ أَقُودُهُمَا ‏ ‏فَلَقِيَنِي رَجُلٌ فَسَاوَمَنِي فَأَبِيعُهُ شَاةً بِدِينَارٍ فَجِئْتُ بِالدِّينَارِ وَجِئْتُ بِالشَّاةِ فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا دِينَارُكُمْ وَهَذِهِ شَاتُكُمْ قَالَ وَصَنَعْتَ كَيْفَ قَالَ فَحَدَّثْتُهُ الْحَدِيثَ فَقَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَهُ فِي صَفْقَةِ يَمِينِهِ ‏ ‏فَلَقَدْ رَأَيْتُنِي أَقِفُ بِكُنَاسَةِ ‏ ‏الْكُوفَةِ ‏ ‏فَأَرْبَحُ أَرْبَعِينَ أَلْفًا قَبْلَ أَنْ أَصِلَ إِلَى أَهْلِي ‏ ‏وَكَانَ يَشْتَرِي الْجَوَارِيَ وَيَبِيعُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرُ بْنُ الْخِرِّيتِ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ وَهُوَ لُمَازَةُ بْنُ زَبَّارٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ الْبَارِقِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[18555,18555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَيْزَارَ بْنَ حُرَيْثٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ الْأَزْدِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ ‏","","",""],[18556,18556,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏حُصَيْنٌ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏الشَّعْبِيَّ ‏ ‏سَمِعَ ‏ ‏عُرْوَةَ بْنَ أَبِي الْجَعْدِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ الْأَجْرُ وَالْمَغْنَمُ ‏","","",""],[18557,18557,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ الْبَارِقِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ الْأَجْرُ وَالْمَغْنَمُ ‏","","",""],[18558,18558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرُ بْنُ الْخِرِّيتِ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏قَالَ كَانَ ‏ ‏عُرْوَةُ بْنُ أَبِي الْجَعْدِ الْبَارِقِيُّ ‏ ‏نَازِلًا بَيْنَ أَظْهُرِنَا فَحَدَّثَ عَنْهُ ‏ ‏أَبُو لَبِيدٍ لُمَازَةُ بْنُ زَبَّارٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏عَرَضَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَلَبٌ ‏ ‏فَأَعْطَانِي دِينَارًا فَقَالَ أَيْ ‏ ‏عُرْوَةُ ‏ ‏ائْتِ ‏ ‏الْجَلَبَ ‏ ‏فَاشْتَرِ لَنَا شَاةً قَالَ فَأَتَيْتُ ‏ ‏الْجَلَبَ ‏ ‏فَسَاوَمْتُ صَاحِبَهُ فَاشْتَرَيْتُ مِنْهُ شَاتَيْنِ بِدِينَارٍ فَجِئْتُ أَسُوقُهُمَا ‏ ‏أَوْ قَالَ أَقُودُهُمَا ‏ ‏فَلَقِيَنِي رَجُلٌ فَسَاوَمَنِي فَأَبِيعُهُ شَاةً بِدِينَارٍ فَجِئْتُ بِالدِّينَارِ وَجِئْتُ بِالشَّاةِ فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا دِينَارُكُمْ وَهَذِهِ شَاتُكُمْ قَالَ وَصَنَعْتَ كَيْفَ فَحَدَّثْتُهُ الْحَدِيثَ فَقَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَهُ فِي صَفْقَةِ يَمِينِهِ ‏ ‏فَلَقَدْ رَأَيْتُنِي أَقِفُ بِكُنَاسَةِ ‏ ‏الْكُوفَةِ ‏ ‏فَأَرْبَحُ أَرْبَعِينَ أَلْفًا قَبْلَ أَنْ أَصِلَ إِلَى أَهْلِي ‏ ‏وَكَانَ يَشْتَرِي الْجَوَارِيَ وَيَبِيعُ ‏","","",""],[18559,18559,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ أَبِي الْجَعْدِ الْبَارِقِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ الْأَجْرُ وَالْمَغْنَمُ ‏","","",""],[18560,18560,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ إِنَّ أَرْضَنَا أَرْضُ صَيْدٍ ‏ ‏فَيَرْمِي أَحَدُنَا الصَّيْدَ فَيَغِيبُ عَنْهُ لَيْلَةً أَوْ لَيْلَتَيْنِ فَيَجِدُهُ وَفِيهِ سَهْمُهُ قَالَ ‏ ‏إِذَا وَجَدْتَ سَهْمَكَ وَلَمْ تَجِدْ فِيهِ أَثَرَ غَيْرِهِ وَعَلِمْتَ أَنَّ سَهْمَكَ قَتَلَهُ فَكُلْهُ ‏","","",""],[18561,18561,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَخْبَرَنَا ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمْ الْخَيْطُ الْأَبْيَضُ مِنْ الْخَيْطِ الْأَسْوَدِ ‏} ‏قَالَ ‏ ‏عَمَدْتُ ‏ ‏إِلَى ‏ ‏عِقَالَيْنِ ‏ ‏أَحَدُهُمَا أَسْوَدُ وَالْآخَرُ أَبْيَضُ فَجَعَلْتُهُمَا تَحْتَ وِسَادِي قَالَ ثُمَّ جَعَلْتُ أَنْظُرُ إِلَيْهِمَا فَلَا تُبِينُ لِي الْأَسْوَدَ مِنْ الْأَبْيَضِ وَلَا الْأَبْيَضَ مِنْ الْأَسْوَدِ فَلَمَّا أَصْبَحْتُ ‏ ‏غَدَوْتُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِالَّذِي صَنَعْتُ فَقَالَ إِنْ كَانَ ‏ ‏وِسَادُكَ ‏ ‏إِذًا لَعَرِيضٌ ‏ ‏إِنَّمَا ذَلِكَ بَيَاضُ النَّهَارِ مِنْ سَوَادِ اللَّيْلِ ‏","","",""],[18562,18562,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُجَالِدٌ ‏ ‏وَزَكَرِيَّا ‏ ‏وَغَيْرُهُمَا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ ‏ ‏الْمِعْرَاضِ ‏ ‏فَقَالَ ‏ ‏مَا أَصَابَ ‏ ‏بِحَدِّهِ ‏ ‏فَخَرَقَ فَكُلْ وَمَا أَصَابَ ‏ ‏بِعَرْضِهِ ‏ ‏فَقَتَلَ فَإِنَّهُ ‏ ‏وَقِيذٌ ‏ ‏فَلَا تَأْكُلْ ‏","","",""],[18563,18563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أُرْسِلُ الْكَلْبَ ‏ ‏الْمُعَلَّمَ ‏ ‏فَيَأْخُذُ قَالَ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ ‏ ‏الْمُعَلَّمَ ‏ ‏وَذَكَرْتَ اسْمَ اللَّهِ عَزَّ وَجَلَّ فَأَخَذَ فَكُلْ قُلْتُ وَإِنْ قَتَلَ قَالَ وَإِنْ قَتَلَ قَالَ قُلْتُ أَرْمِي ‏ ‏بِالْمِعْرَاضِ ‏ ‏قَالَ إِذَا أَصَابَ بِحَدِّهِ فَكُلْ وَإِنْ أَصَابَ ‏ ‏بِعَرْضِهِ ‏ ‏فَلَا تَأْكُلْ ‏","","",""],[18564,18564,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ اللَّهُ عَزَّ وَجَلَّ لَيْسَ بَيْنَهُ وَبَيْنَهُ تَرْجُمَانٌ ثُمَّ يَنْظُرُ أَيْمَنَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ ثُمَّ يَنْظُرُ أَشْأَمَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ ثُمَّ يَنْظُرُ ‏ ‏تِلْقَاءَ ‏ ‏وَجْهِهِ فَتَسْتَقْبِلُهُ النَّارُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَقِيَ وَجْهَهُ النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَلْيَفْعَلْ ‏","","",""],[18565,18565,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏مُرَيِّ بْنِ قَطَرِىٍّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَبِي كَانَ يَصِلُ الرَّحِمَ ‏ ‏وَيَقْرِي ‏ ‏الضَّيْفَ وَيَفْعَلُ كَذَا قَالَ إِنَّ أَبَاكَ أَرَادَ شَيْئًا فَأَدْرَكَهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَرْمِي الصَّيْدَ وَلَا أَجِدُ مَا ‏ ‏أُذَكِّيهِ ‏ ‏بِهِ إِلَّا ‏ ‏الْمَرْوَةَ ‏ ‏وَالْعَصَا قَالَ ‏ ‏أَمَرَّ الدَّمَ بِمَا شِئْتَ ثُمَّ اذْكُرْ اسْمَ اللَّهِ عَزَّ وَجَلَّ قُلْتُ طَعَامٌ مَا أَدَعُهُ إِلَّا تَحَرُّجًا قَالَ مَا ‏ ‏ضَارَعْتَ ‏ ‏فِيهِ نَصْرَانِيَّةً فَلَا فَدَعْهُ ‏","","",""],[18566,18566,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَامِرٌ ‏ ‏حَدَّثَنِي ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قَالَ ‏ ‏عَلَّمَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ وَالصِّيَامَ قَالَ صَلِّ كَذَا وَكَذَا وَصُمْ فَإِذَا غَابَتْ الشَّمْسُ فَكُلْ وَاشْرَبْ حَتَّى يَتَبَيَّنَ لَكَ الْخَيْطُ الْأَبْيَضُ مِنْ الْخَيْطِ الْأَسْوَدِ وَصُمْ ثَلَاثِينَ يَوْمًا إِلَّا أَنْ ‏ ‏تَرَى الْهِلَالَ قَبْلَ ذَلِكَ فَأَخَذْتُ خَيْطَيْنِ مِنْ شَعْرٍ أَسْوَدَ وَأَبْيَضَ فَكُنْتُ أَنْظُرُ فِيهِمَا فَلَا يَتَبَيَّنُ لِي فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَحِكَ وَقَالَ يَا ‏ ‏ابْنَ حَاتِمٍ ‏ ‏إِنَّمَا ذَاكَ بَيَاضُ النَّهَارِ مِنْ سَوَادِ اللَّيْلِ ‏","","",""],[18567,18567,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ قَالَ ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرْمِي الصَّيْدَ فَأَطْلُبُ أَثَرَهُ بَعْدَ لَيْلَةٍ فَأَجِدُ فِيهِ سَهْمِي فَقَالَ ‏ ‏إِذَا وَجَدْتَ فِيهِ سَهْمَكَ وَلَمْ يَأْكُلْ مِنْهُ سَبُعٌ فَكُلْ ‏ ‏فَذَكَرْتُهُ ‏ ‏لِأَبِي بِشْرٍ ‏ ‏فَقَالَ عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَدِيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ وَجَدْتَ فِيهِ سَهْمَكَ تَعْلَمُ أَنَّهُ قَتَلَهُ فَكُلْ ‏","","",""],[18568,18568,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ ‏","","",""],[18569,18569,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏ابْنِ حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أُحَدَّثُ حَدِيثًا عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏فَقُلْتُ هَذَا ‏ ‏عَدِيٌّ ‏ ‏فِي نَاحِيَةِ ‏ ‏الْكُوفَةِ ‏ ‏فَلَوْ أَتَيْتُهُ فَكُنْتُ أَنَا الَّذِي أَسْمَعُهُ مِنْهُ فَأَتَيْتُهُ فَقُلْتُ إِنِّي كُنْتُ أُحَدَّثُ عَنْكَ حَدِيثًا فَأَرَدْتُ أَنْ أَكُونَ أَنَا الَّذِي أَسْمَعُهُ مِنْكَ قَالَ ‏ ‏لَمَّا بَعَثَ اللَّهُ عَزَّ وَجَلَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَرْتُ مِنْهُ حَتَّى كُنْتُ فِي أَقْصَى أَرْضِ الْمُسْلِمِينَ مِمَّا ‏ ‏يَلِي ‏ ‏الرُّومَ ‏ ‏قَالَ فَكَرِهْتُ مَكَانِي الَّذِي أَنَا فِيهِ حَتَّى كُنْتُ لَهُ أَشَدَّ كَرَاهِيَةً لَهُ مِنِّي مِنْ حَيْثُ جِئْتُ قَالَ قُلْتُ لَآتِيَنَّ هَذَا الرَّجُلَ فَوَاللَّهِ إِنْ كَانَ صَادِقًا فَلَأَسْمَعَنَّ مِنْهُ وَإِنْ كَانَ كَاذِبًا مَا هُوَ ‏ ‏بِضَائِرِي ‏ ‏قَالَ فَأَتَيْتُهُ ‏ ‏وَاسْتَشْرَفَنِي ‏ ‏النَّاسُ وَقَالُوا ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قَالَ أَظُنُّهُ قَالَ ثَلَاثَ مِرَارٍ ‏ ‏قَالَ فَقَالَ لِي يَا ‏ ‏عَدِيُّ بْنَ حَاتِمٍ ‏ ‏أَسْلِمْ تَسْلَمْ قَالَ قُلْتُ إِنِّي مِنْ أَهْلِ دِينٍ قَالَ يَا ‏ ‏عَدِيُّ بْنَ حَاتِمٍ ‏ ‏أَسْلِمْ تَسْلَمْ قَالَ قُلْتُ إِنِّي مِنْ أَهْلِ دِينٍ قَالَهَا ثَلَاثًا قَالَ أَنَا أَعْلَمُ بِدِينِكَ مِنْكَ قَالَ قُلْتُ أَنْتَ أَعْلَمُ بِدِينِي مِنِّي قَالَ نَعَمْ قَالَ أَلَيْسَ تَرْأَسُ قَوْمَكَ قَالَ قُلْتُ بَلَى قَالَ فَذَكَرَ ‏ ‏مُحَمَّدٌ ‏ ‏الرَّكُوسِيَّةَ ‏ ‏قَالَ كَلِمَةً الْتَمَسَهَا يُقِيمُهَا فَتَرَكَهَا قَالَ فَإِنَّهُ لَا يَحِلُّ فِي دِينِكَ ‏ ‏الْمِرْبَاعُ ‏ ‏قَالَ فَلَمَّا قَالَهَا تَوَاضَعَتْ مِنِّي ‏ ‏هُنَيَّةٌ ‏ ‏قَالَ وَإِنِّي قَدْ أَرَى أَنَّ مِمَّا يَمْنَعُكَ ‏ ‏خَصَاصَةٌ ‏ ‏تَرَاهَا مِمَّنْ حَوْلِي وَإِنَّ النَّاسَ عَلَيْنَا ‏ ‏أَلْبًا ‏ ‏وَاحِدًا هَلْ تَعْلَمُ مَكَانَ ‏ ‏الْحِيرَةِ ‏ ‏قَالَ قُلْتُ قَدْ سَمِعْتُ بِهَا وَلَمْ آتِهَا قَالَ لَتُوشِكَنَّ ‏ ‏الظَّعِينَةُ ‏ ‏أَنْ تَخْرُجَ مِنْهَا بِغَيْرِ ‏ ‏جِوَارٍ ‏ ‏حَتَّى تَطُوفَ ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏جَوْرٍ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏جَوَازٍ ‏ ‏ثُمَّ رَجَعَ إِلَى حَدِيثِ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏حَتَّى تَطُوفَ ‏ ‏بِالْكَعْبَةِ ‏ ‏وَلَتُوشِكَنَّ كُنُوزُ ‏ ‏كِسْرَى بْنِ هُرْمُزَ ‏ ‏أَنْ تُفْتَحَ قَالَ قُلْتُ ‏ ‏كِسْرَى بْنُ هُرْمُزَ ‏ ‏قَالَ ‏ ‏كِسْرَى بْنُ هُرْمُزَ ‏ ‏قَالَ قُلْتُ ‏ ‏كِسْرَى بْنُ هُرْمُزَ ‏ ‏قَالَ ‏ ‏كِسْرَى بْنُ هُرْمُزَ ‏ ‏ثَلَاثَ مَرَّاتٍ وَلَيُوشِكَنَّ أَنْ يَبْتَغِيَ مَنْ يَقْبَلُ مَالَهُ مِنْهُ ‏ ‏صَدَقَةً ‏ ‏فَلَا يَجِدُ قَالَ فَلَقَدْ رَأَيْتُ ثِنْتَيْنِ قَدْ رَأَيْتُ ‏ ‏الظَّعِينَةَ ‏ ‏تَخْرُجُ مِنْ ‏ ‏الْحِيرَةِ ‏ ‏بِغَيْرِ ‏ ‏جِوَارٍ ‏ ‏حَتَّى تَطُوفَ ‏ ‏بِالْكَعْبَةِ ‏ ‏وَكُنْتُ فِي الْخَيْلِ الَّتِي ‏ ‏غَارَتْ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏أَغَارَتْ ‏ ‏عَلَى الْمَدَائِنِ وَايْمُ اللَّهِ لَتَكُونَنَّ الثَّالِثَةُ إِنَّهُ لَحَدِيثُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنِيهِ ‏","","",""],[18570,18570,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏أَخْبَرَنِي ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَتْ ‏ ‏رَمِيَّتُكَ ‏ ‏فِي الْمَاءِ فَلَا تَأْكُلْ ‏","","",""],[18571,18571,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏أَنَّ رَجُلًا جَاءَهُ يَسْأَلُهُ عَنْ شَيْءٍ اسْتَقَلَّهُ فَحَلَفَ ثُمَّ قَالَ لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرًا خَيْرًا مِنْهَا فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ وَلْيُكَفِّرْ عَنْ يَمِينِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا حَدِيثٌ مَا سَمِعْتُهُ قَطُّ مِنْ أَحَدٍ إِلَّا مِنْ أَبِي ‏","","",""],[18572,18572,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سِمَاكَ بْنَ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَّادَ بْنَ حُبَيْشٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ خَيْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ رُسُلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏بِعَقْرَبٍ ‏ ‏فَأَخَذُوا عَمَّتِي وَنَاسًا قَالَ فَلَمَّا أَتَوْا بِهِمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَصَفُّوا لَهُ قُلْتُ يَا رَسُولَ اللَّهِ نَأَى الْوَافِدُ وَانْقَطَعَ الْوَلَدُ وَأَنَا عَجُوزٌ كَبِيرَةٌ مَا بِي مِنْ خِدْمَةٍ فَمُنَّ عَلَيَّ مَنَّ اللَّهُ عَلَيْكَ قَالَ مَنْ وَافِدُكِ قَالَتْ ‏ ‏عَدِيُّ بْنُ حَاتِمٍ ‏ ‏قَالَ الَّذِي فَرَّ مِنْ اللَّهِ وَرَسُولِهِ قَالَتْ فَمَنَّ عَلَيَّ قَالَتْ فَلَمَّا رَجَعَ وَرَجُلٌ إِلَى جَنْبِهِ نَرَى أَنَّهُ ‏ ‏عَلِىٌّ ‏ ‏قَالَ سَلِيهِ ‏ ‏حِمْلَانًا قَالَ فَسَأَلَتْهُ فَأَمَرَ لَهَا قَالَتْ فَأَتَتْنِي فَقَالَتْ لَقَدْ فَعَلْتَ فَعْلَةً مَا كَانَ أَبُوكَ يَفْعَلُهَا قَالَتْ ائْتِهِ رَاغِبًا أَوْ رَاهِبًا فَقَدْ أَتَاهُ فُلَانٌ فَأَصَابَ مِنْهُ وَأَتَاهُ فُلَانٌ فَأَصَابَ مِنْهُ قَالَ فَأَتَيْتُهُ فَإِذَا عِنْدَهُ امْرَأَةٌ وَصِبْيَانٌ ‏ ‏أَوْ صَبِيٌّ ‏ ‏فَذَكَرَ قُرْبَهُمْ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَفْتُ أَنَّهُ لَيْسَ مُلْكُ ‏ ‏كِسْرَى ‏ ‏وَلَا ‏ ‏قَيْصَرَ ‏ ‏فَقَالَ لَهُ يَا ‏ ‏عَدِيُّ بْنَ حَاتِمٍ ‏ ‏مَا أَفَرَّكَ أَنْ يُقَالَ لَا إِلَهَ إِلَّا اللَّهُ فَهَلْ مِنْ إِلَهٍ إِلَّا اللَّهُ مَا أَفَرَّكَ أَنْ يُقَالَ اللَّهُ أَكْبَرُ فَهَلْ شَيْءٌ هُوَ أَكْبَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ قَالَ فَأَسْلَمْتُ فَرَأَيْتُ وَجْهَهُ اسْتَبْشَرَ وَقَالَ إِنَّ الْمَغْضُوبَ عَلَيْهِمْ ‏ ‏الْيَهُودُ ‏ ‏وَ الضَّالِّينَ ‏ ‏النَّصَارَي ‏ ‏ثُمَّ سَأَلُوهُ فَحَمِدَ اللَّهَ تَعَالَى وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ فَلَكُمْ أَيُّهَا النَّاسُ أَنْ ‏ ‏تَرْضَخُوا ‏ ‏مِنْ الْفَضْلِ ‏ ‏ارْتَضَخَ ‏ ‏امْرُؤٌ ‏ ‏بِصَاعٍ ‏ ‏بِبَعْضِ ‏ ‏صَاعٍ ‏ ‏بِقَبْضَةٍ بِبَعْضِ ‏ ‏قَبْضَةٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَكْثَرُ عِلْمِي أَنَّهُ قَالَ بِتَمْرَةٍ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ إِنَّ أَحَدَكُمْ لَاقِي اللَّهَ عَزَّ وَجَلَّ فَقَائِلٌ مَا أَقُولُ ‏ ‏أَلَمْ أَجْعَلْكَ سَمِيعًا بَصِيرًا أَلَمْ أَجْعَلْ لَكَ مَالًا وَوَلَدًا فَمَاذَا قَدَّمْتَ فَيَنْظُرُ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ وَعَنْ يَمِينِهِ وَعَنْ شِمَالِهِ فَلَا يَجِدُ شَيْئًا فَمَا يَتَّقِي النَّارَ إِلَّا بِوَجْهِهِ فَاتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ فَإِنْ لَمْ تَجِدُوهُ فَبِكَلِمَةٍ ‏ ‏لَيِّنَةٍ ‏ ‏إِنِّي لَا أَخْشَى عَلَيْكُمْ ‏ ‏الْفَاقَةَ ‏ ‏لَيَنْصُرَنَّكُمْ اللَّهُ تَعَالَى وَلَيُعْطِيَنَّكُمْ ‏ ‏أَوْ لَيَفْتَحَنَّ لَكُمْ ‏ ‏حَتَّى تَسِيرَ ‏ ‏الظَّعِينَةُ ‏ ‏بَيْنَ ‏ ‏الْحِيرَةِ ‏ ‏ويَثْرِبَ ‏ ‏أَوْ أَكْثَرَ مَا تَخَافُ السَّرَقَ عَلَى ظَعِينَتِهَا ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏ثَنَاهُ ‏ ‏شُعْبَةُ ‏ ‏مَا لَا أُحْصِيهِ وَقَرَأْتُهُ عَلَيْهِ ‏","","",""],[18573,18573,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ طَرَفَةَ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلَانِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَشَهَّدَ أَحَدُهُمَا فَقَالَ مَنْ يُطِعْ اللَّهَ وَرَسُولَهُ فَقَدْ رَشَدَ وَمَنْ يَعْصِهِمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِئْسَ الْخَطِيبُ أَنْتَ قُمْ ‏","","",""],[18574,18574,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ الْكَلْبِ فَقَالَ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ ‏ ‏الْمُعَلَّمَ ‏ ‏فَسَمَّيْتَ عَلَيْهِ فَأَخَذَ فَأَدْرَكْتَ ‏ ‏ذَكَاتَهُ ‏ ‏فَذَكِّهِ ‏ ‏وَإِنْ قَتَلَ فَكُلْ فَإِنْ أَكَلَ مِنْهُ فَلَا تَأْكُلْ ‏","","",""],[18575,18575,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ حُذَيْفَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏وَلَمْ يَذْكُرْ عَنْ رَجُلٍ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏يَعْنِي كُنْتُ أَسْأَلُ النَّاسَ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏فَذَكَرَ الْحَدِيثَ وَهُوَ إِلَى جَنْبِي لَا أَسْأَلُ عَنْهُ فَأَتَيْتُهُ فَسَأَلْتُهُ فَقَالَ نَعَمْ ‏ ‏بُعِثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ بُعِثَ فَكَرِهْتُهُ أَشَدَّ مَا كَرِهْتُ شَيْئًا قَطُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَدِيِّ بْنِ حَاتِمٍ ‏ ‏حَدِيثٌ بَلَغَنِي عَنْكَ أُحِبُّ أَنْ أَسْمَعَهُ مِنْكَ فَذَكَرَ الْحَدِيثَ ‏","","",""],[18576,18576,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُرَيِّ بْنِ قَطَرِيٍّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ أَبِي ‏ ‏كَانَ يَصِلُ الرَّحِمَ وَيَفْعَلُ وَيَفْعَلُ فَهَلْ لَهُ فِي ذَلِكَ ‏ ‏يَعْنِي مِنْ أَجْرٍ ‏ ‏قَالَ إِنَّ أَبَاكَ طَلَبَ أَمْرًا فَأَصَابَهُ ‏","","",""],[18577,18577,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَعْقِلٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا النَّارَ قَالَ فَأَشَاحَ بِوَجْهِهِ حَتَّى ظَنَنَّا أَنَّهُ يَنْظُرُ إِلَيْهَا ثُمَّ قَالَ اتَّقُوا النَّارَ ‏ ‏وَأَشَاحَ ‏ ‏بِوَجْهِهِ قَالَ قَالَ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏اتَّقُوا النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ فَإِنْ لَمْ تَجِدُوا فَبِكَلِمَةٍ طَيِّبَةٍ ‏","","",""],[18578,18578,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا نَبِيَّ اللَّهِ إِنَّا أَهْلُ صَيْدٍ فَقَالَ ‏ ‏إِذَا رَمَى أَحَدُكُمْ بِسَهْمِهِ فَلْيَذْكُرْ اسْمَ اللَّهِ تَعَالَى فَإِنْ قَتَلَ فَلْيَأْكُلْ وَإِنْ وَقَعَ فِي مَاءٍ فَوَجَدَهُ مَيْتًا فَلَا يَأْكُلْهُ فَإِنَّهُ لَا يَدْرِي لَعَلَّ الْمَاءَ قَتَلَهُ فَإِنْ وَجَدَ سَهْمَهُ فِي صَيْدٍ بَعْدَ يَوْمٍ أَوْ اثْنَيْنِ وَلَمْ يَجِدْ فِيهِ أَثَرًا غَيْرَ سَهْمِهِ فَإِنْ شَاءَ فَلْيَأْكُلْهُ قَالَ وَإِذَا أَرْسَلَ عَلَيْهِ كَلْبَهُ فَلْيَذْكُرْ اسْمَ اللَّهِ عَزَّ وَجَلَّ فَإِنْ أَدْرَكَهُ قَدْ قَتَلَهُ فَلْيَأْكُلْ وَإِنْ أَكَلَ مِنْهُ فَلَا يَأْكُلْ فَإِنَّهُ إِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ وَلَمْ يُمْسِكْ عَلَيْهِ وَإِنْ أَرْسَلَ كَلْبَهُ فَخَالَطَ كِلَابًا لَمْ يَذْكُرْ اسْمَ اللَّهِ عَلَيْهَا فَلَا يَأْكُلْ فَإِنَّهُ لَا يَدْرِي أَيُّهَا قَتَلَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ حُذَيْفَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏قَالَ ‏ ‏قُلْتُ أَسْأَلُ عَنْ حَدِيثِ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏وَأَنَا فِي نَاحِيَةِ ‏ ‏الْكُوفَةِ ‏ ‏أَفَلَا أَكُونُ أَنَا الَّذِي أَسْمَعُهُ فَأَتَيْتُهُ فَقُلْتُ أَتَعْرِفُنِي قَالَ نَعَمْ فَذَكَرَ الْحَدِيثَ وَقَالَ فِيهِ أَلَسْتَ ‏ ‏رَكُوسِيًّا ‏ ‏قُلْتُ بَلَى قَالَ أَوَلَسْتَ تَرْأَسُ قَوْمَكَ فَقُلْتُ بَلَى قَالَ أَوَلَسْتَ تَأْخُذُ ‏ ‏الْمِرْبَاعَ ‏ ‏قَالَ قُلْتُ بَلَى قَالَ ذَاكَ لَا يَحِلُّ لَكَ فِي دِينِكِ قَالَ فَتَوَاضَعَتْ مِنِّي نَفْسِي فَذَكَرَ الْحَدِيثَ ‏","","",""],[18579,18579,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏وَعَاصِمٌ الْأَحْوَلُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَيْدِ ‏ ‏الْمِعْرَاضِ ‏ ‏فَقَالَ ‏ ‏مَا أَصَابَ بِحَدِّهِ فَكُلْ وَمَا أَصَابَ ‏ ‏بِعَرْضِهِ ‏ ‏فَهُوَ ‏ ‏وَقِيذٌ ‏ ‏وَسَأَلْتُ عَنْ صَيْدِ الْكَلْبِ فَقَالَ إِذَا أَرْسَلْتَ كَلْبَكَ وَذَكَرْتَ اسْمَ اللَّهِ عَلَيْهِ فَأَمْسَكَ عَلَيْكَ فَكُلْ وَإِنْ وَجَدْتَ مَعَهُ كَلْبًا غَيْرَ كَلْبِكَ وَقَدْ قَتَلَهُ وَخَشِيتَ أَنْ يَكُونَ قَدْ أَخَذَ مَعَهُ فَلَا تَأْكُلْ فَإِنَّكَ ذَكَرْتَ اسْمَ اللَّهِ عَلَى كَلْبِكَ وَلَمْ تَذْكُرْهُ عَلَى غَيْرِهِ ‏","","",""],[18580,18580,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏وَعَنْ ‏ ‏نَاسٍ ‏ ‏ذَكَرَهُمْ ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَدِيَّ بْنَ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمِعْرَاضِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصَابَ بِحَدِّهِ فَكُلْ وَإِذَا أَصَابَ ‏ ‏بِعَرْضِهِ ‏ ‏فَقَتَلَ فَإِنَّهُ ‏ ‏وَقِيذٌ ‏ ‏فَلَا تَأْكُلْ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أُرْسِلُ كَلْبِي قَالَ إِذَا أَرْسَلْتَ كَلْبَكَ وَسَمَّيْتَ فَأَخَذَ فَكُلْ فَإِذَا أَكَلَ مِنْهُ فَلَا تَأْكُلْ فَإِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أُرْسِلُ كَلْبِي فَأَجِدُ مَعَهُ كَلْبًا آخَرَ لَا أَدْرِي أَيُّهُمَا أَخَذَ قَالَ لَا تَأْكُلْ فَإِنَّمَا سَمَّيْتَ عَلَى كَلْبِكَ وَلَمْ تُسَمِّ عَلَى غَيْرِهِ ‏","","",""],[18581,18581,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ وَسَمَّيْتَ فَخَالَطَ كِلَابًا أُخْرَى فَأَخَذَتْهُ جَمِيعًا فَلَا تَأْكُلْ فَإِنَّكَ لَا تَدْرِي أَيُّهُمَا أَخَذَهُ وَإِذَا رَمَيْتَ فَسَمَّيْتَ فَخَزَقْتَ فَكُلْ فَإِنْ لَمْ ‏ ‏يَتَخَزَّقْ ‏ ‏فَلَا تَأْكُلْ وَلَا تَأْكُلْ مِنْ ‏ ‏الْمِعْرَاضِ ‏ ‏إِلَّا مَا ‏ ‏ذَكَّيْتَ ‏ ‏وَلَا تَأْكُلْ مِنْ الْبُنْدُقَةِ إِلَّا مَا ‏ ‏ذَكَّيْتَ ‏","","",""],[18582,18582,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَن ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أُرْسِلُ كَلْبِي ‏ ‏الْمُكَلَّبَ ‏ ‏قَالَ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ ‏ ‏الْمُكَلَّبَ ‏ ‏وَذَكَرْتَ اسْمَ اللَّهِ فَأَمْسَكَ عَلَيْكَ فَكُلْ قَالَ قُلْتُ وَإِنْ قَتَلَ قَالَ وَإِنْ قَتَلَ مَا لَمْ يُشَارِكْهُ كَلْبٌ غَيْرُهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ فَأَرْمِي ‏ ‏بِالْمِعْرَاضِ ‏ ‏قَالَ مَا ‏ ‏خَزَقَ ‏ ‏فَكُلْ وَمَا أَصَابَ ‏ ‏بِعَرْضِهِ ‏ ‏فَقَتَلَ فَلَا تَأْكُلْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[18583,18583,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فِي شَهْرِ رَمَضَانَ فَلَمَّا غَابَتْ الشَّمْسُ قَالَ انْزِلْ يَا ‏ ‏فُلَانُ ‏ ‏فَاجْدَحْ ‏ ‏لَنَا قَالَ يَا رَسُولَ اللَّهِ عَلَيْكَ نَهَارٌ قَالَ انْزِلْ ‏ ‏فَاجْدَحْ ‏ ‏قَالَ فَفَعَلَ فَنَاوَلَهُ فَشَرِبَ فَلَمَّا شَرِبَ ‏ ‏أَوْمَأَ ‏ ‏بِيَدِهِ إِلَى الْمَغْرِبِ فَقَالَ ‏ ‏إِذَا غَرَبَتْ الشَّمْسُ هَاهُنَا جَاءَ اللَّيْلُ مِنْ هَاهُنَا فَقَدْ أَفْطَرَ الصَّائِمُ ‏","","",""],[18584,18584,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي الْمُجَالِدِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏ابْنُ شَدَّادٍ ‏ ‏وَأَبُو بُرْدَةَ ‏ ‏فَقَالَا انْطَلِقْ إِلَى ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏فَقُلْ لَهُ إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ شَدَّادٍ ‏ ‏وَأَبَا بُرْدَةَ ‏ ‏يُقْرِئَانِكَ السَّلَامَ وَيَقُولَانِ هَلْ كُنْتُمْ ‏ ‏تُسَلِّفُونَ ‏ ‏فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبُرِّ ‏ ‏وَالشَّعِيرِ وَالزَّبِيبِ قَالَ نَعَمْ ‏ ‏كُنَّا نُصِيبُ غَنَائِمَ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُسَلِّفُهَا ‏ ‏فِي ‏ ‏الْبُرِّ ‏ ‏وَالشَّعِيرِ وَالتَّمْرِ وَالزَّبِيبِ فَقُلْتُ عِنْدَ مَنْ كَانَ لَهُ زَرْعٌ أَوْ عِنْدَ مَنْ لَيْسَ لَهُ زَرْعٌ فَقَالَ مَا كُنَّا نَسْأَلُهُمْ عَنْ ذَلِكَ قَالَ وَقَالَا لِي انْطَلِقْ إِلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏فَاسْأَلْهُ قَالَ فَانْطَلَقَ فَسَأَلَهُ فَقَالَ مِثْلَ مَا قَالَ ‏ ‏ابْنُ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏وَكَذَا ‏ ‏حَدَّثَنَاهُ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏قَالَ ‏ ‏وَالزَّيْتِ ‏","","",""],[18585,18585,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضِ ‏ ‏قَالَ ‏ ‏لَا أَدْرِي ‏","","",""],[18586,18586,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يَعْفُورٍ ‏ ‏عَبْدِيٌّ مَوْلًى لَهُمْ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ إِلَى ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏أَسْأَلُهُ عَنْ الْجَرَادِ قَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتَّ غَزَوَاتٍ نَأْكُلُ الْجَرَادَ ‏","","",""],[18587,18587,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَقَالَ ‏ ‏لِرَجُلٍ ‏ ‏انْزِلْ ‏ ‏فَاجْدَحْ ‏ ‏لَنَا ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً يَا رَسُولَ اللَّهِ قَالَ ‏ ‏اجْدَحْ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏اجْدَحْ ‏ ‏فَجَدَحَ ‏ ‏فَشَرِبَ فَلَمَّا شَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْمَأَ ‏ ‏بِيَدِهِ نَحْوَ اللَّيْلِ ‏ ‏إِذَا رَأَيْتُمْ اللَّيْلَ قَدْ أَقْبَلَ مِنْ هَاهُنَا فَقَدْ أَفْطَرَ الصَّائِمُ ‏","","",""],[18588,18588,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏أَصَبْنَا حُمُرًا خَارِجًا مِنْ الْقَرْيَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْفِئُوا ‏ ‏الْقُدُورَ بِمَا فِيهَا ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِسَعِيدِ بْنِ جُبَيْرٍ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا نَهَى عَنْهَا أَنَّهَا كَانَتْ تَأْكُلُ ‏ ‏الْعَذِرَةَ ‏","","",""],[18589,18589,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[18590,18590,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُدْرِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو فَيَقُولُ ‏ ‏اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ اللَّهُمَّ طَهِّرْ قَلْبِي مِنْ الْخَطَايَا كَمَا طَهَّرْتَ الثَّوْبَ الْأَبْيَضَ مِنْ ‏ ‏الدَّنَسِ ‏ ‏وَبَاعِدْ بَيْنِي وَبَيْنَ ذُنُوبِي كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَدُعَاءٍ لَا يُسْمَعُ وَعِلْمٍ لَا يَنْفَعُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ اللَّهُمَّ إِنِّي أَسْأَلُكَ عِيشَةً تَقِيَّةً وَمِيتَةً سَوِيَّةً وَمَرَدًّا غَيْرَ مُخْزٍ ‏","","",""],[18591,18591,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏القَاسِمِ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏مُعَاذٌ ‏ ‏الْيَمَنَ ‏ ‏أَوْ قَالَ ‏ ‏الشَّامَ ‏ ‏فَرَأَى ‏ ‏النَّصَارَى ‏ ‏تَسْجُدُ ‏ ‏لِبَطَارِقَتِهَا ‏ ‏وَأَسَاقِفَتِهَا ‏ ‏فَرَوَّأَ ‏ ‏فِي نَفْسِهِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَقُّ أَنْ يُعَظَّمَ فَلَمَّا قَدِمَ قَالَ يَا رَسُولَ اللَّهِ رَأَيْتُ ‏ ‏النَّصَارَى ‏ ‏تَسْجُدُ ‏ ‏لِبَطَارِقَتِهَا ‏ ‏وَأَسَاقِفَتِهَا ‏ ‏فَرَوَّأْتُ ‏ ‏فِي نَفْسِي أَنَّكَ أَحَقُّ أَنْ تُعَظَّمَ فَقَالَ ‏ ‏لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا وَلَا تُؤَدِّي الْمَرْأَةُ حَقَّ اللَّهِ عَزَّ وَجَلَّ عَلَيْهَا كُلَّهُ حَتَّى تُؤَدِّيَ حَقَّ زَوْجِهَا عَلَيْهَا كُلَّهُ حَتَّى لَوْ سَأَلَهَا نَفْسَهَا وَهِيَ عَلَى ظَهْرِ ‏ ‏قَتَبٍ ‏ ‏لَأَعْطَتْهُ إِيَّاهُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَوْفٍ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏أَحَدِ ‏ ‏بَنِي مُرَّةَ بْنِ هَمَّامٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ جَبَلٍ ‏ ‏قَالَ ‏ ‏إِنَّهُ أَتَى ‏ ‏الشَّامَ ‏ ‏فَرَأَى ‏ ‏النَّصَارَى ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَقُلْتُ لِأَيِّ شَيْءٍ تَصْنَعُونَ هَذَا قَالُوا هَذَا كَانَ تَحِيَّةَ الْأَنْبِيَاءِ قَبْلَنَا فَقُلْتُ نَحْنُ أَحَقُّ أَنْ نَصْنَعَ هَذَا بِنَبِيِّنَا فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُمْ كَذَبُوا عَلَى أَنْبِيَائِهِمْ كَمَا حَرَّفُوا كِتَابَهُمْ إِنَّ اللَّهَ عَزَّ وَجَلَّ أَبْدَلَنَا خَيْرًا مِنْ ذَلِكَ السَّلَامَ تَحِيَّةَ أَهْلِ الْجَنَّةِ ‏","","",""],[18592,18592,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَاهُ قَوْمٌ بِصَدَقَتِهِمْ صَلَّى عَلَيْهِمْ فَأَتَاهُ أَبِي بِصَدَقَتِهِ فَقَالَ اللَّهُمَّ صَلِّ عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18593,18593,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بنِ أَبِي أَوْفَى ‏ ‏هَلْ بَشَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَدِيجَةَ ‏ ‏قَالَ نَعَمْ ‏ ‏بَشَّرَهَا بِبَيْتٍ مِنْ قَصَبٍ لَا ‏ ‏صَخَبٌ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبٌ ‏","","",""],[18594,18594,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏ثُمَّ خَرَجَ فَطَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَجَعَلْنَا نَسْتُرُهُ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏أَنْ يَرْمِيَهُ أَحَدٌ ‏ ‏أَوْ يُصِيبَهُ ‏ ‏بِشَيْءٍ فَسَمِعْتُهُ يَدْعُو عَلَى الْأَحْزَابِ يَقُولُ ‏ ‏اللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ هَازِمَ الْأَحْزَابِ اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ ‏","","",""],[18595,18595,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَوْصَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ قَالَ لَا قُلْتُ فَكَيْفَ أَمْرَ الْمُسْلِمِينَ بِالْوَصِيَّةِ قَالَ ‏ ‏أَوْصَى بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏قَالَ ‏ ‏طَلْحَةُ ‏ ‏وَقَالَ ‏ ‏الْهُزَيْلُ بْنُ شُرَحْبِيلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏كَانَ يَتَأَمَّرُ عَلَى وَصِيِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أَنَّهُ وَجَدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهْدًا ‏ ‏فَخُزِمَ ‏ ‏أَنْفُهُ ‏ ‏بِخِزَامٍ ‏","","",""],[18596,18596,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ أَبِي إِسْمَاعِيلَ السَّكْسَكِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي لَا أَقْرَأُ الْقُرْآنَ فَمُرْنِي بِمَا يُجْزِئُنِي مِنْهُ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ ‏ ‏الْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ فَقَالَهَا الرَّجُلُ وَقَبَضَ كَفَّهُ وَعَدَّ خَمْسًا مَعَ إِبْهَامِهِ فَقَالَ يَا رَسُولَ اللَّهِ هَذَا لِلَّهِ تَعَالَى فَمَا لِنَفْسِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي قَالَ فَقَالَهَا وَقَبَضَ عَلَى كَفِّهِ الْأُخْرَى وَعَدَّ خَمْسًا مَعَ إِبْهَامِهِ فَانْطَلَقَ الرَّجُلُ وَقَدْ قَبَضَ كَفَّيْهِ جَمِيعًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ مَلَأَ كَفَّيْهِ مِنْ الْخَيْرِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَكَانَ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏فَائِدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَاهُ غُلَامٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ هَاهُنَا غُلَامًا يَتِيمًا لَهُ أُمٌّ أَرْمَلَةٌ وَأُخْتٌ يَتِيمَةٌ أَطْعِمْنَا مِمَّا أَطْعَمَكَ اللَّهُ تَعَالَى أَعْطَاكَ اللَّهُ مِمَّا عِنْدَهُ حَتَّى ‏ ‏تَرْضَى فَذَكَرَ الْحَدِيثَ بِطُولِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَكَانَ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏فَائِدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ هَاهُنَا غُلَامًا قَدْ ‏ ‏احْتُضِرَ ‏ ‏يُقَالُ لَهُ قُلْ لَا إِلَهَ إِلَّا اللَّهُ فَلَا يَسْتَطِيعُ أَنْ يَقُولَهَا فَقَالَ أَلَيْسَ كَانَ يَقُولُ فِي حَيَاتِهِ قَالَ بَلَى قَالَ فَمَا مَنَعَهُ مِنْهَا عِنْدَ مَوْتِهِ فَذَكَرَ الْحَدِيثَ بِطُولِهِ ‏ ‏فَلَمْ يُحَدِّثْنَا أَبِي بِهَذَيْنِ الْحَدِيثَيْنِ ‏ ‏ضَرَبَ ‏ ‏عَلَيْهِمَا مِنْ كِتَابِهِ لِأَنَّهُ لَمْ يَرْضَ حَدِيثَ ‏ ‏فَائِدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَكَانَ ‏ ‏عِنْدَهُ مَتْرُوكَ الْحَدِيثِ ‏","","",""],[18597,18597,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمُخْتَارِ ‏ ‏مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏أَصَابَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ عَطَشٌ قَالَ فَنَزَلَ مَنْزِلًا فَأُتِيَ بِإِنَاءٍ فَجَعَلَ يَسْقِي أَصْحَابَهُ وَجَعَلُوا يَقُولُونَ اشْرَبْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاقِي الْقَوْمِ آخِرُهُمْ حَتَّى سَقَاهُمْ كُلَّهُمْ ‏","","",""],[18598,18598,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَهُوَ صَائِمٌ فَدَعَا صَاحِبَ شَرَابِهِ بِشَرَابٍ فَقَالَ صَاحِبُ شَرَابِهِ لَوْ أَمْسَيْتَ يَا رَسُولَ اللَّهِ ثُمَّ دَعَاهُ فَقَالَ لَهُ لَوْ أَمْسَيْتَ ثَلَاثًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ اللَّيْلُ مِنْ هَاهُنَا فَقَدْ حَلَّ الْإِفْطَارُ ‏ ‏أَوْ كَلِمَةً هَذَا مَعْنَاهَا ‏","","",""],[18599,18599,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ جُمْهَانَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُمْهَانَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏يُقَاتِلُ ‏ ‏الْخَوَارِجَ ‏ ‏وَقَدْ لَحِقَ غُلَامٌ ‏ ‏لِابْنِ أَبِي أَوْفَى ‏ ‏بِالْخَوَارِجِ ‏ ‏فَنَادَيْنَاهُ يَا ‏ ‏فَيْرُوزُ ‏ ‏هَذَا ‏ ‏ابْنُ أَبِي أَوْفَى ‏ ‏قَالَ نِعْمَ الرَّجُلُ لَوْ هَاجَرَ قَالَ مَا يَقُولُ عَدُوُّ اللَّهِ قَالَ يَقُولُ نِعْمَ الرَّجُلُ لَوْ هَاجَرَ فَقَالَ هِجْرَةٌ بَعْدَ هِجْرَتِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَدِّدُهَا ثَلَاثًا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طُوبَى ‏ ‏لِمَنْ قَتَلَهُمْ ثُمَّ قَتَلُوهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ وَقَتَلُوهُ ثَلَاثًا ‏","","",""],[18600,18600,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَشْرَجُ ابْنُ نُبَاتَةَ الْعَبْسِيُّ كُوفِيٌّ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُمْهَانَ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏وَهُوَ مَحْجُوبُ الْبَصَرِ فَسَلَّمْتُ عَلَيْهِ قَالَ لِي مَنْ أَنْتَ فَقُلْتُ أَنَا ‏ ‏سَعِيدُ بْنُ جُمْهَانَ ‏ ‏قَالَ فَمَا فَعَلَ وَالِدُكَ قَالَ قُلْتُ قَتَلَتْهُ ‏ ‏الْأَزَارِقَةُ ‏ ‏قَالَ لَعَنَ اللَّهُ ‏ ‏الْأَزَارِقَةَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْأَزَارِقَةَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ كِلَابُ النَّارِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏الْأَزَارِقَةُ ‏ ‏وَحْدَهُمْ أَمْ ‏ ‏الْخَوَارِجُ ‏ ‏كُلُّهَا ‏ ‏قَالَ ‏ ‏بَلَى ‏ ‏الْخَوَارِجُ ‏ ‏كُلُّهَا قَالَ قُلْتُ فَإِنَّ السُّلْطَانَ يَظْلِمُ النَّاسَ وَيَفْعَلُ بِهِمْ قَالَ فَتَنَاوَلَ يَدِي فَغَمَزَهَا ‏ ‏بِيَدِهِ غَمْزَةً شَدِيدَةً ثُمَّ قَالَ وَيْحَكَ يَا ‏ ‏ابْنَ جُمْهَانَ ‏ ‏عَلَيْكَ بِالسَّوَادِ الْأَعْظَمِ عَلَيْكَ بِالسَّوَادِ الْأَعْظَمِ إِنْ كَانَ السُّلْطَانُ يَسْمَعُ مِنْكَ فَأْتِهِ فِي بَيْتِهِ فَأَخْبِرْهُ بِمَا تَعْلَمُ فَإِنْ قَبِلَ مِنْكَ وَإِلَّا فَدَعْهُ فَإِنَّكَ لَسْتَ بِأَعْلَمَ مِنْهُ ‏","","",""]];
